// GENERATED by scripts/build-index.js from the subject files in this folder. Do not edit; run: node scripts/build-index.js
StudyData.addIndex(11, {"accountancy":{"syllabus":{"board":"CBSE","match":"textbook","books":["Financial Accounting Part I","Financial Accounting Part II"],"reviewed":false},"chapters":[{"id":"introduction-to-accounting","title":"Introduction to Accounting","section":"Financial Accounting","summary":"What accounting is, its role as an information system, its users, the qualitative characteristics of accounting information, its objectives and limitations, and basic terms such as assets, liabilities, capital, revenue and expenses.","nTerms":6},{"id":"theory-base-of-accounting","title":"Theory Base of Accounting","section":"Financial Accounting","summary":"Generally Accepted Accounting Principles, the basic accounting concepts, accounting standards (AS and Ind AS), cash and accrual bases of accounting, and an introduction to Goods and Services Tax (GST).","nTerms":6},{"id":"recording-of-transactions-1","title":"Recording of Transactions – I","section":"Financial Accounting","summary":"Source documents and vouchers, the accounting equation, rules of debit and credit, recording in the journal, posting to the ledger and balancing accounts, including entries with GST.","nTerms":6},{"id":"recording-of-transactions-2","title":"Recording of Transactions – II","section":"Financial Accounting","summary":"Special purpose books: the cash book (simple, with bank column, and petty cash book), the purchases, sales, purchases return and sales return books, and the journal proper.","nTerms":6},{"id":"bank-reconciliation-statement","title":"Bank Reconciliation Statement","section":"Financial Accounting","summary":"Why the bank column of the cash book and the pass book show different balances, and how to reconcile them through a bank reconciliation statement, including overdrafts and the amended cash book.","nTerms":6},{"id":"trial-balance-and-rectification-of-errors","title":"Trial Balance and Rectification of Errors","section":"Financial Accounting","summary":"Preparing a trial balance to check the arithmetical accuracy of the ledger, the types of errors, errors disclosed and not disclosed by a trial balance, the suspense account, and rectification of errors.","nTerms":6},{"id":"depreciation-provisions-and-reserves","title":"Depreciation, Provisions and Reserves","section":"Financial Accounting","summary":"Meaning, causes and need for depreciation, the straight line and written down value methods, ways of recording depreciation and disposal of assets, and the difference between provisions and reserves.","nTerms":6},{"id":"financial-statements-1","title":"Financial Statements – I","section":"Financial Accounting","summary":"Objectives and users of financial statements, capital and revenue items, preparing the trading and profit and loss account and the balance sheet of a sole proprietor, operating profit, and opening and closing entries.","nTerms":6},{"id":"financial-statements-2","title":"Financial Statements – II","section":"Financial Accounting","summary":"Adjustments while preparing final accounts: closing stock, outstanding and prepaid expenses, accrued income and income received in advance, depreciation, bad debts and provisions, manager's commission, interest on capital and drawings, and abnormal loss.","nTerms":6}]},"biology":{"syllabus":{"board":"CBSE","match":"textbook","books":["Biology"],"reviewed":false},"chapters":[{"id":"the-living-world","title":"The Living World","section":"Diversity in the Living World","summary":"Living organisms show enormous diversity. This chapter covers the features that define life, why we classify organisms, binomial nomenclature, and the taxonomic hierarchy from species to kingdom.","nTerms":6},{"id":"biological-classification","title":"Biological Classification","section":"Diversity in the Living World","summary":"R.H. Whittaker's five-kingdom system groups organisms by cell structure, body organisation, nutrition, reproduction and phylogeny. This chapter covers Monera, Protista and Fungi in detail, along with viruses, viroids, prions and lichens.","nTerms":6},{"id":"plant-kingdom","title":"Plant Kingdom","section":"Diversity in the Living World","summary":"Kingdom Plantae includes algae, bryophytes, pteridophytes, gymnosperms and angiosperms. This chapter covers the systems of plant classification and the key features, examples and importance of each group.","nTerms":6},{"id":"animal-kingdom","title":"Animal Kingdom","section":"Diversity in the Living World","summary":"Animals are classified using levels of organisation, symmetry, germ layers, coelom, segmentation and notochord. This chapter covers the distinctive features and examples of every non-chordate phylum and of each chordate class.","nTerms":6},{"id":"morphology-of-flowering-plants","title":"Morphology of Flowering Plants","section":"Structural Organisation","summary":"Morphology is the study of the external form of plants. This chapter covers the root, stem and leaf with their modifications, inflorescence, the parts of a flower, placentation, fruits and seeds.","nTerms":6},{"id":"anatomy-of-flowering-plants","title":"Anatomy of Flowering Plants","section":"Structural Organisation","summary":"Anatomy is the study of internal structure. This chapter covers meristems, simple and complex permanent tissues, the three tissue systems, and the internal structure of dicot and monocot roots, stems and leaves.","nTerms":6},{"id":"structural-organisation-in-animals","title":"Structural Organisation in Animals","section":"Structural Organisation","summary":"Cells with similar structure and function form tissues. This chapter covers the four basic animal tissues (epithelial, connective, muscular and neural) and the morphology and organ systems of the frog.","nTerms":6},{"id":"cell-the-unit-of-life","title":"Cell: The Unit of Life","section":"Cell: Structure and Function","summary":"The cell is the basic structural and functional unit of life. This chapter covers cell theory, prokaryotic cells, the plasma membrane and cell wall, the endomembrane system, mitochondria, plastids, ribosomes, the cytoskeleton, cilia, centrosome and the nucleus.","nTerms":6},{"id":"biomolecules","title":"Biomolecules","section":"Cell: Structure and Function","summary":"All living tissues are built from a few kinds of chemical compounds. This chapter covers amino acids, lipids, nitrogenous bases, carbohydrates, proteins, nucleic acids and enzymes, the biological catalysts that drive metabolism.","nTerms":6},{"id":"cell-cycle-and-cell-division","title":"Cell Cycle and Cell Division","section":"Cell: Structure and Function","summary":"Cells reproduce by dividing. This chapter covers the phases of the cell cycle, the stages of mitosis and cytokinesis, and meiosis with its stages of prophase I, and why each division matters.","nTerms":6},{"id":"photosynthesis-in-higher-plants","title":"Photosynthesis in Higher Plants","section":"Plant Physiology","summary":"Photosynthesis is the process by which green plants make food using light. This chapter covers early experiments, pigments, the light reaction with photosystems, the Calvin cycle, C₄ plants, photorespiration and limiting factors.","nTerms":6},{"id":"respiration-in-plants","title":"Respiration in Plants","section":"Plant Physiology","summary":"Respiration breaks down food to release energy. This chapter covers glycolysis, fermentation, the Krebs cycle, the electron transport system, oxidative phosphorylation, the amphibolic pathway and the respiratory quotient.","nTerms":6},{"id":"plant-growth-and-development","title":"Plant Growth and Development","section":"Plant Physiology","summary":"Growth and development in plants are controlled by internal and external factors. This chapter covers growth phases and rates, differentiation, the five plant growth regulators, photoperiodism and vernalisation.","nTerms":6},{"id":"breathing-and-exchange-of-gases","title":"Breathing and Exchange of Gases","section":"Human Physiology","summary":"Breathing brings oxygen to the body and removes carbon dioxide. This chapter covers the human respiratory system, mechanism of breathing, lung volumes, exchange and transport of gases, regulation of respiration and common disorders.","nTerms":6},{"id":"body-fluids-and-circulation","title":"Body Fluids and Circulation","section":"Human Physiology","summary":"Blood and lymph carry nutrients, gases and wastes around the body. This chapter covers blood composition, blood groups, coagulation, lymph, the human heart, cardiac cycle, ECG, double circulation and common disorders.","nTerms":6},{"id":"excretory-products-and-their-elimination","title":"Excretory Products and their Elimination","section":"Human Physiology","summary":"Animals remove nitrogenous wastes and maintain water and ion balance. This chapter covers modes of excretion, the human excretory system, nephron structure, urine formation, regulation of kidney function and disorders.","nTerms":6},{"id":"locomotion-and-movement","title":"Locomotion and Movement","section":"Human Physiology","summary":"Movement is a defining feature of animals. This chapter covers the types of movement, the structure of skeletal muscle, the sliding filament theory, the human skeleton, joints and common muscular and skeletal disorders.","nTerms":6},{"id":"neural-control-and-coordination","title":"Neural Control and Coordination","section":"Human Physiology","summary":"The nervous system coordinates the body's activities rapidly. This chapter covers neurons, nerve impulses and synapses, the human brain, reflex action, and the structure and working of the eye and ear.","nTerms":6},{"id":"chemical-coordination-and-integration","title":"Chemical Coordination and Integration","section":"Human Physiology","summary":"Hormones from endocrine glands coordinate the body along with the nervous system. This chapter covers the endocrine glands, their hormones, mechanism of hormone action and the disorders caused by hormonal imbalance.","nTerms":6}]},"business":{"syllabus":{"board":"CBSE","match":"textbook","books":["Business Studies"],"reviewed":false},"chapters":[{"id":"business-trade-and-commerce","title":"Business, Trade and Commerce","section":"Foundations of Business","summary":"The nature and purpose of business: what business is, how it differs from profession and employment, how business activities are classified into industry and commerce, the objectives and risks of business, and a look at India's long history of trade.","nTerms":6},{"id":"forms-of-business-organisation","title":"Forms of Business Organisation","section":"Foundations of Business","summary":"The main forms of business ownership in India: sole proprietorship, Joint Hindu Family business, partnership, cooperative society and joint stock company, with their features, merits, limitations and the factors that decide which form to choose.","nTerms":6},{"id":"private-public-and-global-enterprises","title":"Private, Public and Global Enterprises","section":"Foundations of Business","summary":"India's mixed economy has private and public sector enterprises. This chapter covers the three forms of public enterprises, the changing role of the public sector after 1991, global enterprises (MNCs), joint ventures and public private partnership.","nTerms":6},{"id":"business-services","title":"Business Services","section":"Foundations of Business","summary":"The nature and types of services, with a focus on banking (types of banks and accounts, drafts, RTGS/NEFT, overdraft, cash credit, e-banking and digital payments), insurance (principles and types) and postal services.","nTerms":6},{"id":"emerging-modes-of-business","title":"Emerging Modes of Business","section":"Foundations of Business","summary":"How computer networks have changed business: the meaning and scope of e-business, its benefits and limitations, how online transactions and payments work, and the risks and safeguards in e-business.","nTerms":6},{"id":"social-responsibility-and-business-ethics","title":"Social Responsibility of Business and Business Ethics","section":"Foundations of Business","summary":"Why business has duties to society beyond earning profit: the meaning and kinds of social responsibility, arguments for and against it, responsibilities towards different groups, protecting the environment, CSR under the Companies Act, 2013 and the elements of business ethics.","nTerms":6},{"id":"sources-of-business-finance","title":"Sources of Business Finance","section":"Corporate Organisation, Finance and Trade","summary":"Why business needs finance and where it comes from: classification of sources, owners' funds (equity, preference shares, retained earnings), borrowed funds (debentures, loans, public deposits, trade credit, ICDs), short-term sources, international sources (GDR, ADR, IDR, FCCB) and how to choose a source.","nTerms":6},{"id":"small-business-and-entrepreneurship","title":"Small Business and Entrepreneurship","section":"Corporate Organisation, Finance and Trade","summary":"How micro, small and medium enterprises are defined, their role in India and especially in rural areas, their problems and government support (NSIC, DIC), and the concept of entrepreneurship, Startup India, ways to fund a startup and intellectual property rights.","nTerms":6},{"id":"internal-trade","title":"Internal Trade","section":"Corporate Organisation, Finance and Trade","summary":"Buying and selling within the country: the services of wholesalers and retailers, types of retail trade (itinerant, small fixed shops, departmental stores and chain stores), and the Goods and Services Tax (GST).","nTerms":6},{"id":"international-business","title":"International Business","section":"Corporate Organisation, Finance and Trade","summary":"Business across national borders: why it happens, its benefits, the ways firms enter foreign markets, the export and import procedures, the documents used in international trade, and the World Trade Organization.","nTerms":6}]},"chemistry":{"syllabus":{"board":"CBSE","match":"textbook","books":["Chemistry Part I","Chemistry Part II"],"reviewed":false},"chapters":[{"id":"some-basic-concepts-of-chemistry","title":"Some Basic Concepts of Chemistry","section":"Physical Chemistry","summary":"The language of chemical calculations: measurement and significant figures, laws of chemical combination, atomic and molecular masses, the mole concept, empirical and molecular formulae, stoichiometry, limiting reagent and concentration terms.","nTerms":6},{"id":"structure-of-atom","title":"Structure of Atom","section":"Physical Chemistry","summary":"From the discovery of electrons, protons and neutrons to the quantum mechanical model: atomic models, quantisation of energy, Bohr's model of hydrogen, dual nature of matter, the uncertainty principle, quantum numbers, orbitals and electronic configuration.","nTerms":6},{"id":"classification-of-elements-and-periodicity","title":"Classification of Elements and Periodicity in Properties","section":"Inorganic Chemistry","summary":"How elements came to be arranged in the periodic table, the modern periodic law, IUPAC names of new elements, the s, p, d and f blocks, and periodic trends in atomic radius, ionisation enthalpy, electron gain enthalpy, electronegativity and chemical reactivity.","nTerms":6},{"id":"chemical-bonding-and-molecular-structure","title":"Chemical Bonding and Molecular Structure","section":"Inorganic Chemistry","summary":"Why and how atoms combine: the octet rule, ionic and covalent bonds, bond parameters, resonance and polarity, VSEPR shapes, valence bond theory and hybridisation, molecular orbital theory, and hydrogen bonding.","nTerms":6},{"id":"thermodynamics","title":"Thermodynamics","section":"Physical Chemistry","summary":"Energy changes in chemical reactions: systems and state functions, the first law, work and enthalpy, Hess's law and enthalpies of reaction, and how entropy and Gibbs energy decide whether a process is spontaneous.","nTerms":6},{"id":"equilibrium","title":"Equilibrium","section":"Physical Chemistry","summary":"Physical and chemical equilibria, the law of mass action, Kc and Kp, Le Chatelier's principle, acids and bases, pH, ionisation of weak acids, buffers, salt hydrolysis and solubility product.","nTerms":6},{"id":"redox-reactions","title":"Redox Reactions","section":"Physical Chemistry","summary":"Oxidation and reduction as electron transfer, oxidation numbers, types of redox reactions, balancing redox equations by the oxidation-number and half-reaction methods, and the link between redox reactions and electrode potentials.","nTerms":6},{"id":"organic-chemistry-basic-principles","title":"Organic Chemistry – Some Basic Principles and Techniques","section":"Organic Chemistry","summary":"The foundation of organic chemistry: structures and classification of organic compounds, IUPAC naming, isomerism, electron displacement effects and reactive intermediates, and methods to purify and analyse organic compounds.","nTerms":6},{"id":"hydrocarbons","title":"Hydrocarbons","section":"Organic Chemistry","summary":"Preparation, properties and reactions of alkanes, alkenes, alkynes and aromatic hydrocarbons, including conformations of ethane, Markovnikov's rule and the peroxide effect, ozonolysis, acidity of alkynes, aromaticity and electrophilic substitution in benzene.","nTerms":6}]},"economics":{"syllabus":{"board":"CBSE","match":"textbook","books":["Statistics for Economics","Introductory Microeconomics"],"note":"Arranged as CBSE examines it in Class 11.","reviewed":false},"chapters":[{"id":"stats-introduction","title":"Introduction to Statistics","section":"Statistics for Economics","summary":"Why economics is the study of choices made under scarcity, the roles of consumers, producers, service holders and service providers, and how statistics (as data and as a set of methods) helps economists understand economic problems.","nTerms":6},{"id":"collection-of-data","title":"Collection of Data","section":"Statistics for Economics","summary":"Primary and secondary sources of data, how to design a good questionnaire and choose a survey method, census versus sample surveys, random and non-random sampling, sampling and non-sampling errors, and India's main data agencies: the Census of India and the NSSO.","nTerms":6},{"id":"organisation-of-data","title":"Organisation of Data","section":"Statistics for Economics","summary":"How raw data are classified (chronological, spatial, qualitative, quantitative), the difference between discrete and continuous variables, and how to build frequency distributions using class intervals, tally marks and the exclusive and inclusive methods.","nTerms":6},{"id":"presentation-of-data","title":"Presentation of Data","section":"Statistics for Economics","summary":"The three ways to present data: textual, tabular and diagrammatic. Covers the parts of a good table, bar and pie diagrams, histograms, frequency polygons and curves, ogives and arithmetic line graphs.","nTerms":6},{"id":"measures-of-central-tendency","title":"Measures of Central Tendency","section":"Statistics for Economics","summary":"Averages that sum up a whole data set with one representative value: the arithmetic mean (simple and weighted), the median and the mode, how to calculate them for individual, discrete and continuous series, and when to use which.","nTerms":6},{"id":"correlation","title":"Correlation","section":"Statistics for Economics","summary":"How two variables move together: positive and negative correlation, the scatter diagram, Karl Pearson's coefficient of correlation and Spearman's rank correlation, and why correlation does not mean causation.","nTerms":6},{"id":"index-numbers","title":"Index Numbers","section":"Statistics for Economics","summary":"Index numbers measure changes in a group of related variables (such as prices or production) over time. Covers simple and weighted price indices (Laspeyres, Paasche), the CPI, WPI, IIP and Sensex, and their use in measuring inflation and real wages.","nTerms":6},{"id":"micro-introduction","title":"Introduction to Microeconomics","section":"Introductory Microeconomics","summary":"What economics studies: scarcity and choice, the central problems of an economy, the production possibility frontier and opportunity cost, how economic activities are organised, and the difference between microeconomics and macroeconomics.","nTerms":6},{"id":"theory-of-consumer-behaviour","title":"Theory of Consumer Behaviour","section":"Introductory Microeconomics","summary":"How a consumer chooses the best bundle of goods with a limited income: cardinal utility (TU, MU), indifference curves and MRS, the budget line, the consumer's optimum, demand and its determinants, and price elasticity of demand.","nTerms":6},{"id":"production-and-costs","title":"Production and Costs","section":"Introductory Microeconomics","summary":"How a firm turns inputs into output (production function, total, average and marginal product, the law of variable proportions, returns to scale) and how its costs behave in the short run and the long run.","nTerms":6},{"id":"theory-of-firm-under-perfect-competition","title":"The Theory of the Firm under Perfect Competition","section":"Introductory Microeconomics","summary":"How a price-taking firm decides how much to produce: revenue concepts, the conditions of profit maximisation (p = MC), shut-down and break-even points, the firm's and the market supply curve, and price elasticity of supply.","nTerms":6},{"id":"market-equilibrium","title":"Market Equilibrium","section":"Introductory Microeconomics","summary":"How demand and supply together fix the price and quantity of a good: equilibrium with a fixed number of firms and with free entry and exit, effects of shifts in demand and supply, the labour market, and government price controls (price ceiling and price floor).","nTerms":6}]},"english":{"syllabus":{"board":"CBSE","match":"textbook","books":["Hornbill","Snapshots"],"note":"Grammar and writing skills, plus every lesson of Hornbill and Snapshots (summarised in our own words).","reviewed":false},"chapters":[{"id":"determiners","title":"Determiners","section":"Grammar","summary":"Choosing the right determiner before a noun (articles, demonstratives, possessives, quantifiers and distributives such as each, every, either and neither) in gap-filling and editing tasks.","nTerms":6},{"id":"tenses","title":"Tenses","section":"Grammar","summary":"Using all twelve tense forms accurately, with special attention to perfect and continuous forms, time expressions, stative verbs and sequence of tenses, as tested in gap-filling and editing passages.","nTerms":6},{"id":"clauses","title":"Clauses","section":"Grammar","summary":"Identifying and using main and subordinate clauses, the three kinds of subordinate clauses (noun, adjective/relative and adverb), and choosing the right connecting word in gap-filling tasks.","nTerms":6},{"id":"modals","title":"Modals","section":"Grammar","summary":"Using modal auxiliaries to express ability, permission, possibility, obligation, advice and past deduction, including perfect modals such as should have, must have and needn't have.","nTerms":6},{"id":"editing-error-correction","title":"Editing and Error Correction","section":"Grammar","summary":"Spotting and correcting errors of tense, subject–verb agreement, determiners, prepositions, pronouns and word forms in sentences and short passages.","nTerms":5},{"id":"reordering-transformation","title":"Reordering and Transformation of Sentences","section":"Grammar","summary":"Rearranging jumbled words into meaningful sentences and transforming sentences (voice, narration, degree, too…to, combining) without changing their meaning.","nTerms":6},{"id":"notice-writing","title":"Notice","section":"Writing Skills","summary":"Writing a short, boxed notice of about 50 words that informs readers about an event, meeting, competition or lost-and-found item, with every key detail in the correct format.","nTerms":5},{"id":"poster-making","title":"Poster","section":"Writing Skills","summary":"Designing an eye-catching poster of about 50 words that announces an event or spreads awareness about a social issue, using a slogan, key details and the issuing authority.","nTerms":5},{"id":"speech-writing","title":"Speech","section":"Writing Skills","summary":"Writing a speech of 120–150 words for a school assembly or function, with a proper greeting, self-introduction, well-organised points and a strong conclusion.","nTerms":5},{"id":"debate-writing","title":"Debate","section":"Writing Skills","summary":"Arguing for or against a motion in 120–150 words, with a formal greeting, a clear stand, logical arguments, a rebuttal of the other side and a firm conclusion.","nTerms":5},{"id":"the-portrait-of-a-lady","title":"The Portrait of a Lady","section":"Hornbill","summary":"Khushwant Singh's affectionate sketch of his grandmother: their close bond in the village, the growing distance as he moved to the city and went abroad, and her peaceful death, mourned by thousands of sparrows.","nTerms":6},{"id":"were-not-afraid-to-die","title":"We're Not Afraid to Die... if We Can All Be Together","section":"Hornbill","summary":"A true account of a family's round-the-world voyage that turns into a fight for survival when a giant wave wrecks their boat in the southern Indian Ocean, and how courage, teamwork and the children's bravery see them through.","nTerms":6},{"id":"discovering-tut","title":"Discovering Tut: the Saga Continues","section":"Hornbill","summary":"An account of how scientists in 2005 used a CT scanner to study the mummy of the boy-king Tutankhamun, more than 3,300 years after his death, in an effort to find out how he lived and died.","nTerms":6},{"id":"a-photograph","title":"A Photograph","section":"Hornbill","summary":"A poem in which the poet looks at an old seaside photograph of her mother as a girl and reflects on the passing of time, memory, and her grief at her mother's death.","nTerms":5},{"id":"the-laburnum-top","title":"The Laburnum Top","section":"Hornbill","summary":"Ted Hughes's short poem about a still, silent laburnum tree that bursts into noisy life when a goldfinch slips inside to feed her young, and falls empty again when she flies off.","nTerms":6},{"id":"the-voice-of-the-rain","title":"The Voice of the Rain","section":"Hornbill","summary":"Walt Whitman's short poem in which the rain itself answers the poet, describing its endless cycle from earth to sky and back, and comparing itself to a song that returns to its source.","nTerms":6},{"id":"the-ailing-planet","title":"The Ailing Planet: the Green Movement's Role","section":"Hornbill","summary":"Nani Palkhivala's 1994 essay on the Green Movement: the earth is a living organism in poor health, forests and other life-support systems are being destroyed, population growth makes it worse, and everyone, including industry, must act responsibly for future generations.","nTerms":6},{"id":"childhood","title":"Childhood","section":"Hornbill","summary":"A reflective poem in which the poet asks when his childhood ended, and suggests it was lost as he began to think logically, saw through adults' hypocrisy and discovered his own individuality.","nTerms":6},{"id":"the-adventure","title":"The Adventure","section":"Hornbill","summary":"Jayant Narlikar's science-fiction story: after a road accident, historian Gangadharpant Gaitonde finds himself in a Bombay where the Marathas won the Battle of Panipat and the British never took over India. His scientist friend Rajendra explains it through catastrophe theory and parallel worlds.","nTerms":6},{"id":"silk-road","title":"Silk Road","section":"Hornbill","summary":"Nick Middleton's travelogue of his journey through Tibet towards Mount Kailash: crossing a 5,500-metre pass with his driver Tsetan, falling ill with a cold and altitude trouble at Darchen, and finding a companion in Norbu for the kora.","nTerms":6},{"id":"father-to-son","title":"Father to Son","section":"Hornbill","summary":"A father's lament about the gap between himself and his grown-up son: though they live in the same house, they cannot understand each other, and both long for a reconciliation they cannot achieve.","nTerms":6},{"id":"the-summer-of-the-beautiful-white-horse","title":"The Summer of the Beautiful White Horse","section":"Snapshots","summary":"A humorous story about two poor Armenian boys, Aram and his cousin Mourad, who secretly keep a farmer's white horse to enjoy riding it, and finally return it because their family is known for its honesty.","nTerms":5},{"id":"the-address","title":"The Address","section":"Snapshots","summary":"Set after the Second World War, this story follows a young Jewish woman who visits the address where her mother had left the family's possessions, and decides to forget it when she finds the objects have lost their meaning.","nTerms":5},{"id":"mothers-day","title":"Mother's Day","section":"Snapshots","summary":"A comic one-act play in which an overworked, neglected housewife, Mrs Pearson, swaps personalities with her bold neighbour Mrs Fitzgerald, who then teaches the Pearson family to respect her.","nTerms":5},{"id":"birth","title":"Birth","section":"Snapshots","summary":"An episode from A.J. Cronin's novel The Citadel in which a young doctor, Andrew Manson, attends a difficult birth in a Welsh mining town and brings an apparently stillborn baby back to life.","nTerms":5},{"id":"the-tale-of-melon-city","title":"The Tale of Melon City","section":"Snapshots","summary":"A humorous verse tale by Vikram Seth about a ‘just and placid’ king whose foolish orders lead to his own hanging, after which a melon is crowned king: a satire on rulers and the crowd.","nTerms":6}]},"englishpb":{"syllabus":{"board":"PSEB","match":"textbook","books":["A Panorama of Life (PSEB, Class 11)","English Grammar and Composition for XI and XII (PSEB)"],"note":"Follows the PSEB 2026–27 syllabus; lessons summarised in our own words from the PSEB textbook (2023–24 edition).","reviewed":false},"chapters":[{"id":"prepositions","title":"Prepositions","section":"Grammar","summary":"A preposition shows the relation between a noun or pronoun and another word. This chapter covers prepositions of time, place and direction, and common verb, adjective and noun + preposition pairs.","nTerms":5},{"id":"determiners","title":"Determiners","section":"Grammar","summary":"Determiners are words placed before a noun to show which one, how many or how much: articles, demonstratives, possessives, quantifiers and numbers.","nTerms":5},{"id":"same-word-noun-verb-adjective","title":"Same Word as Noun, Verb and Adjective","section":"Grammar","summary":"Many English words keep the same spelling but change part of speech with their position and use in the sentence; some also change stress or spelling slightly.","nTerms":5},{"id":"modals","title":"Modals","section":"Grammar","summary":"Modal auxiliaries (can, could, may, might, shall, should, will, would, must, ought to, need, dare) express ability, permission, possibility, obligation, advice and willingness.","nTerms":5},{"id":"tenses","title":"Tenses","section":"Grammar","summary":"The twelve tense forms: simple, continuous, perfect and perfect continuous in the present, past and future, with their main uses and time expressions.","nTerms":5},{"id":"removal-use-of-too","title":"Removal and Use of 'Too'","section":"Grammar","summary":"How to use 'too' correctly (excess, or in the sense of also) and how to rewrite 'too ... to' sentences using 'so ... that' or 'very'.","nTerms":5},{"id":"voice","title":"Voice","section":"Grammar","summary":"Active and passive voice: how to change a sentence from active to passive and back in the common tenses, with questions, imperatives and modals.","nTerms":5},{"id":"narration","title":"Narration","section":"Grammar","summary":"Direct and indirect speech: how to report what someone said, with changes in tense, pronouns, time and place words, and for statements, questions, commands and exclamations.","nTerms":5},{"id":"note-making","title":"Note Making","section":"Writing","summary":"Note making means recording the main ideas of a passage in a short, organised form using a title, headings, sub-headings, abbreviations and a key.","nTerms":5},{"id":"message-and-notice-writing","title":"Message and Notice Writing","section":"Writing","summary":"A message is a short written communication to a person who is absent; a notice informs a group about an event. Both must be brief, clear and complete.","nTerms":5},{"id":"advertisement-writing","title":"Advertisement Writing","section":"Writing","summary":"An advertisement draws attention to a product, service, event or vacancy. Classified ads are short and paid by the word; display ads use headlines, slogans and layout.","nTerms":5},{"id":"letter-writing-social-personal","title":"Letter Writing (Social and Personal)","section":"Writing","summary":"Social and personal letters are written to friends, relatives and acquaintances for congratulations, condolence, invitation, thanks or news. The tone is informal or semi-formal.","nTerms":5},{"id":"translation-tips","title":"Translation Tips","section":"Writing","summary":"Practical rules for translating passages from Punjabi (or Hindi) into natural English: tenses, word order, idioms and common pitfalls.","nTerms":5},{"id":"gender-bias","title":"Gender Bias","section":"Prose","summary":"Sudha Murthy recalls how, as the only girl in her postgraduate class at the Indian Institute of Science, she saw a Telco job advertisement closed to women, wrote a protest postcard to J. R. D. Tata, was called for an interview, and became the first woman engineer on the company's shop floor.","nTerms":5},{"id":"the-portrait-of-a-lady","title":"The Portrait of a Lady","section":"Prose","summary":"Khushwant Singh's affectionate sketch of his grandmother: their close bond in the village, the growing distance as he moved to the city and abroad, and her peaceful death mourned by sparrows.","nTerms":5},{"id":"liberty-and-discipline","title":"Liberty and Discipline","section":"Prose","summary":"Field Marshal Sir William Slim argues that liberty and discipline go together: discipline is a restraint on freedom, yet every society must have it, and the real question is whether it comes from within, by understanding, or is forced from outside. A leader must first discipline himself.","nTerms":5},{"id":"a-president-speaks","title":"A President Speaks","section":"Prose","summary":"In a speech at Hyderabad, Dr A. P. J. Abdul Kalam states his three visions for India - freedom, development and standing up to the world - and urges Indians to stop only complaining and to do their part, by keeping the country clean, obeying rules and taking responsibility.","nTerms":5},{"id":"the-earth-is-not-ours","title":"The Earth is not Ours","section":"Prose","summary":"In his address to the Millennium Summit of the United Nations in 2000, Secretary General Kofi Annan describes globalisation and groups the world's problems under three freedoms: freedom from want, freedom from fear and the freedom of future generations to live on this planet.","nTerms":5},{"id":"lets-not-forget-the-martyrs","title":"Let's Not Forget the Martyrs","section":"Prose","summary":"Compiled by Vandana Sehgal, this piece recalls five winners of the Param Vir Chakra, India's highest gallantry award: Major Somnath Sharma, Major Dhan Singh Thapa, Havildar Abdul Hamid, Flying Officer Nirmal Jit Singh Sekhon and Captain Vikram Batra.","nTerms":5},{"id":"water-a-true-elixir","title":"Water - A True Elixir","section":"Prose","summary":"Dr D. V. Jindal explains why water is the most precious resource after air, how little of it is drinkable, how ancient societies conserved it, and why the falling water table in Punjab, caused by paddy and heavy tubewell use, calls for urgent conservation.","nTerms":5},{"id":"no-time-for-fear","title":"No Time for Fear","section":"Prose","summary":"Philip Yancey tells the true story of Malcolm Aspeslet, a nineteen-year-old Canadian who saved his girlfriend Barb Beck from a grizzly bear in 1971, was terribly injured, and was loved and married by Barb in spite of his scars.","nTerms":5},{"id":"lines-written-in-early-spring","title":"Lines Written in Early Spring","section":"Poetry","summary":"William Wordsworth's reflective poem in which the poet, lying in a grove in spring, feels the joy of nature and mourns what humans have done to humans.","nTerms":5},{"id":"mothers-day","title":"Mother's Day","section":"Poetry","summary":"Shiv K. Kumar's short poem rejects the Western custom of honouring a mother once a year with a card or bouquet. For the poet, in India a mother deserves respect every day, like a deity worshipped at every sunrise.","nTerms":5},{"id":"upagupta","title":"Upagupta","section":"Poetry","summary":"Rabindranath Tagore's narrative poem about the young Buddhist ascetic Upagupta, who politely declines the invitation of the dancing girl Vasavadatta in Mathura, and returns less than a year later to nurse her when she is abandoned with smallpox.","nTerms":5},{"id":"confessions-of-a-born-spectator","title":"Confessions of a Born Spectator","section":"Poetry","summary":"Ogden Nash's humorous poem in which the poet confesses that he is a watcher, not a doer, and playfully admires and teases sportsmen and sportswomen.","nTerms":5},{"id":"the-little-black-boy","title":"The Little Black Boy","section":"Poetry","summary":"William Blake's poem, from Songs of Innocence, in which a black child tells how his mother taught him that God loves all and that colour is only a cloud that will fade in heaven.","nTerms":5},{"id":"a-thing-of-beauty","title":"A Thing of Beauty","section":"Poetry","summary":"The opening lines of John Keats's long poem Endymion, which declare that beauty brings lasting joy, drives away sorrow and links us with the world around us.","nTerms":5},{"id":"an-astrologers-day","title":"An Astrologer's Day","section":"Extensive Study","summary":"R. K. Narayan's story of a roadside astrologer who earns by shrewd guessing rather than knowledge of the stars, and is startled one night when a client turns out to be the man he once stabbed and left for dead.","nTerms":5},{"id":"the-tiger-in-the-tunnel","title":"The Tiger in the Tunnel","section":"Extensive Study","summary":"Ruskin Bond's story of Baldeo, a tribal watchman at a lonely jungle signal post, who fights a tiger with his axe to protect his sleeping son and the line, and dies; the tiger is killed by the mail train, and his twelve-year-old son Tembu takes over his duty.","nTerms":5},{"id":"sparrows","title":"Sparrows","section":"Extensive Study","summary":"K. A. Abbas's story of Rahim Khan, a hard-hearted peasant hated by his village, who was embittered when his youthful dreams were crushed by tradition. A pair of sparrows nesting in his hut bring out his hidden kindness, but too late.","nTerms":5},{"id":"the-model-millionaire","title":"The Model Millionaire","section":"Extensive Study","summary":"Oscar Wilde's short story in which a kind-hearted, poor young man, Hughie Erskine, gives a coin to a shabby beggar who turns out to be a very rich baron, and is rewarded with a wedding gift.","nTerms":5},{"id":"panch-parmeshwar","title":"Panch Parmeshwar","section":"Extensive Study","summary":"Premchand's story of two close friends, Jumman Sheikh and Algu Chowdhari. Each, when made sarpanch in a dispute involving the other, puts justice before friendship, showing that a seat of judgement makes a person speak like God.","nTerms":5},{"id":"the-peasants-bread","title":"The Peasant's Bread","section":"Extensive Study","summary":"Leo Tolstoy's moral tale in which an imp fails to make a poor peasant swear when his only bread is stolen, then succeeds by giving him surplus grain, which the peasant turns into vodka, showing how excess brings out the animal in man.","nTerms":5}]},"geography":{"syllabus":{"board":"CBSE","match":"textbook","books":["Fundamentals of Physical Geography","India: Physical Environment"],"reviewed":false},"chapters":[{"id":"geography-as-a-discipline","title":"Geography as a Discipline","section":"Fundamentals of Physical Geography","summary":"What geography studies, how it integrates the natural and social sciences, the systematic and regional approaches, and the branches of geography, with a focus on physical geography.","nTerms":6},{"id":"origin-and-evolution-of-the-earth","title":"The Origin and Evolution of the Earth","section":"Fundamentals of Physical Geography","summary":"Early and modern theories of the origin of the universe and the earth, the formation of stars and planets, the solar system and the moon, and the evolution of the earth's layers, atmosphere, oceans and life.","nTerms":6},{"id":"interior-of-the-earth","title":"Interior of the Earth","section":"Fundamentals of Physical Geography","summary":"How we know about the earth's interior, earthquakes and seismic waves, shadow zones, the structure of the earth (crust, mantle, core), and volcanoes with their extrusive and intrusive landforms.","nTerms":6},{"id":"distribution-of-oceans-and-continents","title":"Distribution of Oceans and Continents","section":"Fundamentals of Physical Geography","summary":"Wegener's continental drift theory and its evidence, the ocean floor and sea-floor spreading, the theory of plate tectonics with major plates and plate boundaries, and the movement of the Indian plate.","nTerms":6},{"id":"geomorphic-processes","title":"Geomorphic Processes","section":"Fundamentals of Physical Geography","summary":"Endogenic and exogenic forces that shape the earth's surface: diastrophism and volcanism, weathering and its types, mass movements, erosion and deposition, and the factors of soil formation.","nTerms":6},{"id":"landforms-and-their-evolution","title":"Landforms and their Evolution","section":"Fundamentals of Physical Geography","summary":"Erosional and depositional landforms made by running water, groundwater, glaciers, waves and currents, and winds, and the stages through which landscapes evolve.","nTerms":6},{"id":"composition-and-structure-of-atmosphere","title":"Composition and Structure of Atmosphere","section":"Fundamentals of Physical Geography","summary":"The gases, water vapour and dust particles that make up the atmosphere, the layers of the atmosphere from the troposphere to the exosphere, and the elements of weather and climate.","nTerms":6},{"id":"solar-radiation-heat-balance-and-temperature","title":"Solar Radiation, Heat Balance and Temperature","section":"Fundamentals of Physical Geography","summary":"How the earth receives insolation and why it varies, how the atmosphere is heated, the heat budget of the earth, factors controlling temperature, the distribution of temperature, and inversion of temperature.","nTerms":6},{"id":"atmospheric-circulation-and-weather-systems","title":"Atmospheric Circulation and Weather Systems","section":"Fundamentals of Physical Geography","summary":"Atmospheric pressure and pressure belts, forces that drive winds, the general circulation of the atmosphere and ENSO, local winds, air masses and fronts, and weather systems such as extra-tropical and tropical cyclones, thunderstorms and tornadoes.","nTerms":6},{"id":"water-in-the-atmosphere","title":"Water in the Atmosphere","section":"Fundamentals of Physical Geography","summary":"Humidity and its measures, evaporation and condensation, forms of condensation (dew, frost, fog, mist, clouds), types of precipitation and rainfall, and the world distribution of rainfall.","nTerms":6},{"id":"world-climate-and-climate-change","title":"World Climate and Climate Change","section":"Fundamentals of Physical Geography","summary":"Koeppen's scheme of climate classification, the major climatic groups of the world, and the evidence, causes and effects of climate change including global warming.","nTerms":6},{"id":"water-oceans","title":"Water (Oceans)","section":"Fundamentals of Physical Geography","summary":"The hydrological cycle, relief of the ocean floor, and the temperature and salinity of ocean water.","nTerms":6},{"id":"movements-of-ocean-water","title":"Movements of Ocean Water","section":"Fundamentals of Physical Geography","summary":"Waves, tides and ocean currents: how they form, their types and their effects on climate and human activity.","nTerms":6},{"id":"biodiversity-and-conservation","title":"Biodiversity and Conservation","section":"Fundamentals of Physical Geography","summary":"The meaning and levels of biodiversity, its distribution and importance, loss and threats, and conservation approaches including hotspots and international efforts.","nTerms":6},{"id":"india-location","title":"India – Location","section":"India: Physical Environment","summary":"India's latitudinal and longitudinal extent, its size, standard time, neighbours and the strategic importance of its location.","nTerms":5},{"id":"structure-and-physiography","title":"Structure and Physiography","section":"India: Physical Environment","summary":"The geological structure of India and its six physiographic divisions: the Northern Mountains, Northern Plain, Peninsular Plateau, Indian Desert, Coastal Plains and Islands.","nTerms":6},{"id":"drainage-system","title":"Drainage System","section":"India: Physical Environment","summary":"The Himalayan and peninsular rivers of India, their origin, courses and tributaries, and the main lakes.","nTerms":6},{"id":"climate-of-india","title":"Climate","section":"India: Physical Environment","summary":"The monsoon climate of India: controls, mechanism of the monsoon, the four seasons and the pattern of rainfall.","nTerms":6},{"id":"natural-vegetation","title":"Natural Vegetation","section":"India: Physical Environment","summary":"The major forest types of India, their distribution and trees, the wildlife of India and conservation efforts.","nTerms":5},{"id":"natural-hazards-and-disasters","title":"Natural Hazards and Disasters","section":"India: Physical Environment","summary":"Natural hazards and disasters, their classification, major disasters in India (earthquakes, tsunami, cyclones, floods, landslides, droughts) and disaster management.","nTerms":6}]},"hindi":{"syllabus":{"board":"CBSE","match":"textbook","books":["Aroh Bhag 1","Vitan Bhag 1"],"note":"Every lesson of Aroh and Vitan (summarised in our own words), plus selected Abhivyakti aur Madhyam writing chapters.","reviewed":false},"chapters":[{"id":"namak-ka-daroga","title":"नमक का दारोगा","section":"आरोह","summary":"प्रेमचंद की इस कहानी में ईमानदार दारोगा वंशीधर और धनी ज़मींदार पंडित अलोपीदीन के माध्यम से धन और धर्म (ईमानदारी) के संघर्ष का चित्रण है। अंत में ईमानदारी की ही जीत होती है।","nTerms":6},{"id":"miyan-nasiruddin","title":"मियाँ नसीरुद्दीन","section":"आरोह","summary":"कृष्णा सोबती के इस शब्दचित्र में दिल्ली के खानदानी नानबाई मियाँ नसीरुद्दीन के व्यक्तित्व, उनकी बातचीत के अंदाज़ और अपने पेशे पर उनके गर्व का सजीव चित्रण है।","nTerms":6},{"id":"apu-ke-saath-dhai-saal","title":"अपू के साथ ढाई साल","section":"आरोह","summary":"सत्यजित राय के इस संस्मरण में उनकी पहली फ़िल्म 'पथेर पांचाली' की शूटिंग के ढाई साल के अनुभव हैं – पैसों की तंगी, बार-बार रुकती शूटिंग और जुगाड़ से निकाले गए रास्ते। पाठ दिखाता है कि पर्दे की सहजता के पीछे कितना संघर्ष होता है।","nTerms":6},{"id":"vidai-sambhashan","title":"विदाई-संभाषण","section":"आरोह","summary":"बालमुकुंद गुप्त के व्यंग्य-निबंध 'शिवशंभु के चिट्ठे' का यह अंश वायसराय लॉर्ड कर्ज़न को विदाई देने के बहाने उनके शासन की ज़िद, पक्षपात और प्रजा की उपेक्षा पर तीखा व्यंग्य करता है।","nTerms":6},{"id":"galta-loha","title":"गलता लोहा","section":"आरोह","summary":"शेखर जोशी की इस कहानी में पुरोहित परिवार के मेधावी मोहन और लोहार के बेटे धनराम के माध्यम से शिक्षा-व्यवस्था की खामियों, बेरोज़गारी और जातिगत भेदभाव के टूटने का चित्रण है।","nTerms":6},{"id":"rajni","title":"रजनी","section":"आरोह","summary":"मन्नू भंडारी की इस पटकथा (टी.वी. धारावाहिक 'रजनी' की एक कड़ी) में निडर स्त्री-पात्र रजनी स्कूलों में ट्यूशन के नाम पर चल रही धाँधली के खिलाफ़ लड़ती है। पाठ पटकथा विधा से परिचय कराता है और व्यावसायिक होती शिक्षा की समस्या उठाता है।","nTerms":6},{"id":"jamun-ka-ped","title":"जामुन का पेड़","section":"आरोह","summary":"कृश्नचंदर की इस हास्य-व्यंग्य कथा में सेक्रेटेरियट के लॉन में गिरे जामुन के पेड़ के नीचे दबे एक आदमी की फ़ाइल विभागों में घूमती रहती है और अंत में उसकी जान चली जाती है। कहानी लालफ़ीताशाही और संवेदनहीन सरकारी तंत्र पर करारा व्यंग्य है।","nTerms":6},{"id":"bharat-mata","title":"भारत माता","section":"आरोह","summary":"जवाहरलाल नेहरू की 'हिंदुस्तान की कहानी' का यह अंश बताता है कि वे जलसों में किसानों से भारत की एकता की चर्चा कैसे करते थे और 'भारत माता की जय' का सही अर्थ क्या है – देश के करोड़ों लोग ही भारत माता हैं।","nTerms":6},{"id":"kabir-ke-pad","title":"कबीर के पद","section":"आरोह","summary":"पाठ्यपुस्तक के पद 'हम तौ एक एक करि जांनां' में कबीर बताते हैं कि परमात्मा एक है और हवा, पानी, ज्योति की तरह कण-कण में समाया है। जो उसे दो मानते हैं, वे सत्य से दूर हैं; सत्य जान लेने पर कबीर निर्भय हो गए हैं।","nTerms":6},{"id":"mira-ke-pad","title":"मीरा के पद","section":"आरोह","summary":"पाठ्यपुस्तक के पद 'मेरे तो गिरधर गोपाल, दूसरो न कोई' में मीरा कृष्ण के प्रति अपनी अनन्यता व्यक्त करती हैं, लोक-लाज और कुल की मर्यादा छोड़ने की बात कहती हैं और बताती हैं कि भक्तों को देखकर वे प्रसन्न होती हैं तथा संसार को देखकर रोती हैं।","nTerms":6},{"id":"ghar-ki-yaad","title":"घर की याद","section":"आरोह","summary":"भवानी प्रसाद मिश्र की इस कविता में जेल में बंद कवि बरसात की एक रात अपने घर-परिवार, विशेषकर माता-पिता को याद करता है और सावन को संदेशवाहक बनाकर पिता के पास भेजता है।","nTerms":5},{"id":"champa-kale-kale-achchhar","title":"चंपा काले काले अच्छर नहीं चीन्हती","section":"आरोह","summary":"त्रिलोचन की इस कविता में एक पढ़ने वाला कवि और अनपढ़ ग्वाले की चंचल लड़की चंपा आमने-सामने हैं। कवि उसे पढ़ने को कहता है, पर चंपा पढ़ाई को ही अपने भावी वियोग (पति के कलकत्ता जाने) से जोड़कर विद्रोह करती है। कविता प्रवास और शिक्षा-व्यवस्था की विडंबना को दिखाती है।","nTerms":6},{"id":"ghazal-dushyant-kumar","title":"ग़ज़ल (दुष्यंत कुमार)","section":"आरोह","summary":"दुष्यंत कुमार की इस ग़ज़ल (संग्रह 'साये में धूप') में आज के राजनीतिक और सामाजिक हालात के प्रति असंतोष है। शेर बताते हैं कि वादे झूठे निकले, आम आदमी बुनियादी चीज़ों से वंचित है, फिर भी कवि बदलाव की उम्मीद और आवाज़ में असर की चाह रखता है।","nTerms":6},{"id":"akka-mahadevi-ke-vachan","title":"अक्कमहादेवी के वचन","section":"आरोह","summary":"वीर शैव आंदोलन की कवयित्री अक्कमहादेवी के दो वचन हैं। पहले में वे इंद्रियों और मनोविकारों से संयम की प्रेमभरी मनुहार करती हैं, दूसरे में अपने आराध्य चन्नमल्लिकार्जुन के प्रति पूर्ण समर्पण और निस्पृहता की कामना करती हैं।","nTerms":6},{"id":"sabse-khatarnak","title":"सबसे ख़तरनाक","section":"आरोह","summary":"पंजाबी कवि पाश की इस कविता में बताया गया है कि मेहनत की लूट, पुलिस की मार या गद्दारी-लोभ उतने ख़तरनाक नहीं, जितना ख़तरनाक है मुर्दा शांति से भर जाना, तड़प का न होना और सपनों का मर जाना।","nTerms":6},{"id":"aao-milkar-bachayen","title":"आओ, मिलकर बचाएँ","section":"आरोह","summary":"संथाली कवयित्री निर्मला पुतुल की इस कविता में आदिवासी जीवन की उन चीज़ों को बचाने का आह्वान है – अपनी भाषा, संस्कृति, प्रकृति, सादगी और जुझारूपन – जो विस्थापन, शहरीकरण और नशे से संकट में हैं। अंत में कवयित्री कहती है कि बचाने को अब भी बहुत कुछ बचा है।","nTerms":6},{"id":"lata-mangeshkar","title":"भारतीय गायिकाओं में बेजोड़ : लता मंगेशकर","section":"वितान","summary":"प्रसिद्ध शास्त्रीय गायक कुमार गंधर्व ने इस लेख में लता मंगेशकर की गायकी की विशेषताओं, चित्रपट संगीत और शास्त्रीय संगीत के संबंध तथा आम लोगों की संगीत-रुचि पर लता के प्रभाव का विश्लेषण किया है।","nTerms":6},{"id":"rajasthan-ki-rajat-boondein","title":"राजस्थान की रजत बूँदें","section":"वितान","summary":"अनुपम मिश्र के इस लेख में राजस्थान के मरुस्थल में पानी जुटाने की पारंपरिक संरचना 'कुंई' और उसे बनाने वाले कुशल कारीगरों (चेलवांजी) का वर्णन है। यह जल-संरक्षण के लोक-ज्ञान और सामाजिक व्यवस्था को सामने लाता है।","nTerms":6},{"id":"aalo-aandhari","title":"आलो-आँधारि","section":"वितान","summary":"बेबी हालदार की आत्मकथा 'आलो-आँधारि' (अर्थ – अँधेरे का उजाला) के इस अंश में घरेलू नौकरानी बेबी बच्चों के साथ अकेले रहने की मुश्किलों, मकान टूटने के संकट और 'तातुश' के घर मिले सहारे की कथा कहती है। तातुश के प्रोत्साहन से वह लिखना शुरू करती है और अंत में पत्रिका में अपना नाम देखती है।","nTerms":6},{"id":"bharatiya-kalayen","title":"भारतीय कलाएँ","section":"वितान","summary":"यह पाठ भारतीय चित्रकला, संगीत और नृत्य की परंपरा का परिचय देता है। इसमें दिखाया गया है कि हमारी कलाएँ लोक से शास्त्रीय रूप तक आईं, त्योहारों-ऋतुओं और जीवन से जुड़ी हैं तथा उनमें सामूहिकता और प्रकृति-प्रेम की भावना है।","nTerms":6},{"id":"jansanchar-madhyam","title":"जनसंचार माध्यम","section":"अभिव्यक्ति और माध्यम (लेखन)","summary":"संचार और जनसंचार का अर्थ, संचार के तत्व और प्रकार, जनसंचार के कार्य तथा समाचार-पत्र, रेडियो, टेलीविज़न, सिनेमा और इंटरनेट जैसे प्रमुख जनसंचार माध्यमों का परिचय।","nTerms":6},{"id":"patrakarita-ke-vividh-aayam","title":"पत्रकारिता के विविध आयाम","section":"अभिव्यक्ति और माध्यम (लेखन)","summary":"पत्रकारिता और समाचार का अर्थ, समाचार के तत्व, संपादन के सिद्धांत, पत्रकारों के प्रकार तथा खोजपरक, विशेषीकृत, वॉचडॉग, एडवोकेसी, पीत और पेज थ्री जैसी पत्रकारिता के विविध रूपों का परिचय।","nTerms":6},{"id":"vibhinn-madhyamon-ke-liye-lekhan","title":"विभिन्न माध्यमों के लिए लेखन","section":"अभिव्यक्ति और माध्यम (लेखन)","summary":"प्रिंट, रेडियो, टेलीविज़न और इंटरनेट – हर माध्यम की प्रकृति अलग है, इसलिए हर एक के लिए लेखन के नियम भी अलग हैं। इस अध्याय में इन माध्यमों की खूबियाँ, सीमाएँ और लेखन की विशेष बातें दी गई हैं।","nTerms":6},{"id":"samachar-lekhan","title":"समाचार लेखन","section":"अभिव्यक्ति और माध्यम (लेखन)","summary":"समाचार लेखन छह ककारों – क्या, कौन, कहाँ, कब, क्यों और कैसे – के उत्तर पर आधारित होता है और प्रायः उलटा पिरामिड शैली में लिखा जाता है, जिसमें सबसे महत्त्वपूर्ण बात सबसे पहले आती है।","nTerms":5},{"id":"feature-lekhan","title":"फ़ीचर लेखन","section":"अभिव्यक्ति और माध्यम (लेखन)","summary":"फ़ीचर एक सुव्यवस्थित, सृजनात्मक और आत्मनिष्ठ लेखन है, जो सूचना और शिक्षा के साथ मुख्य रूप से पाठकों का मनोरंजन करता है। इस अध्याय में फ़ीचर का स्वरूप, समाचार से अंतर, प्रकार और लिखने का ढंग दिया गया है।","nTerms":5},{"id":"karyalayi-patra","title":"कार्यालयी पत्र","section":"अभिव्यक्ति और माध्यम (लेखन)","summary":"सरकारी या गैर-सरकारी कार्यालयों, अधिकारियों और संस्थाओं को शिकायत, अनुरोध या आवेदन के लिए लिखे जाने वाले पत्र कार्यालयी पत्र कहलाते हैं। इनमें निश्चित प्रारूप, शिष्ट और तथ्यपरक भाषा तथा संक्षिप्तता आवश्यक है।","nTerms":6},{"id":"rachnatmak-lekhan","title":"रचनात्मक लेखन","section":"अभिव्यक्ति और माध्यम (लेखन)","summary":"रचनात्मक लेखन में लेखक अपनी कल्पना, अनुभव और संवेदना से मौलिक रचना करता है। इस अध्याय में रचनात्मक लेखन का स्वरूप, उसके गुण, कहानी-कविता-नाटक के मूल तत्व और परीक्षा में अप्रत्याशित विषयों पर लिखने का ढंग दिया गया है।","nTerms":6}]},"hindipb":{"syllabus":{"board":"PSEB","match":"textbook","books":["हिंदी भाषा बोध और व्याकरण (PSEB)","हिंदी साहित्य का इतिहास (PSEB)"],"note":"PSEB 2026–27 syllabus: grammar, history of Hindi literature and writing. Textbook lessons are not included.","reviewed":false},"chapters":[{"id":"sandhi-swar","title":"संधि: स्वर संधि","section":"व्याकरण","summary":"दो निकटवर्ती वर्णों के मेल से होने वाले विकार को संधि कहते हैं। स्वर के बाद स्वर आने पर जो संधि होती है, वह स्वर संधि कहलाती है। इसके पाँच भेद हैं – दीर्घ, गुण, वृद्धि, यण और अयादि।","nTerms":5},{"id":"sandhi-vyanjan-visarg","title":"संधि: व्यंजन और विसर्ग संधि","section":"व्याकरण","summary":"व्यंजन के बाद स्वर या व्यंजन आने पर होने वाले परिवर्तन को व्यंजन संधि कहते हैं। विसर्ग (ः) के बाद स्वर या व्यंजन आने पर होने वाला परिवर्तन विसर्ग संधि कहलाता है।","nTerms":5},{"id":"vakya-vishleshan","title":"वाक्य विश्लेषण और संश्लेषण","section":"व्याकरण","summary":"रचना के आधार पर वाक्य तीन प्रकार के होते हैं – सरल, संयुक्त और मिश्र। वाक्य को उसके खंडों में बाँटना विश्लेषण है और अलग-अलग वाक्यों को जोड़कर एक वाक्य बनाना संश्लेषण है।","nTerms":6},{"id":"paribhashik-shabdavali","title":"पारिभाषिक शब्दावली","section":"व्याकरण","summary":"प्रशासन, विधि, शिक्षा, विज्ञान आदि क्षेत्रों में किसी विशेष अर्थ में प्रयुक्त निश्चित शब्दों को पारिभाषिक शब्द कहते हैं। इनमें अंग्रेज़ी के तकनीकी शब्दों के लिए हिंदी के मानक पर्याय प्रयोग किए जाते हैं।","nTerms":5},{"id":"ras-1","title":"रस (भाग 1): शृंगार, करुण, हास्य, शांत, रौद्र","section":"व्याकरण","summary":"काव्य को पढ़ने-सुनने से मिलने वाले आनंद को रस कहते हैं। रस के चार अंग हैं – स्थायी भाव, विभाव, अनुभाव और संचारी भाव। इस भाग में शृंगार, करुण, हास्य, शांत और रौद्र रस पढ़ेंगे।","nTerms":5},{"id":"ras-2","title":"रस (भाग 2): वीर, अद्भुत, भयानक, वीभत्स और रस के अंग","section":"व्याकरण","summary":"वीर, अद्भुत, भयानक और वीभत्स – ये शेष चार रस हैं। रस के चार अंग हैं – स्थायी भाव, विभाव, अनुभाव और संचारी भाव, जिनके मेल से रस की निष्पत्ति होती है।","nTerms":6},{"id":"kaal-vibhajan","title":"हिंदी साहित्य का काल-विभाजन","section":"साहित्य का इतिहास","summary":"हिंदी साहित्य के इतिहास को प्रवृत्तियों के आधार पर कालों में बाँटा गया है। आचार्य रामचंद्र शुक्ल का विभाजन सबसे अधिक प्रचलित है – आदिकाल (वीरगाथा काल), भक्तिकाल, रीतिकाल और आधुनिक काल।","nTerms":4},{"id":"aadikal","title":"आदिकाल (वीरगाथा काल)","section":"साहित्य का इतिहास","summary":"आदिकाल (वि.सं. 1050–1375) में वीर रस प्रधान रासो काव्य रचे गए। चंदबरदाई, अमीर खुसरो और विद्यापति इस काल के प्रमुख रचनाकार हैं।","nTerms":5},{"id":"bhakti-nirgun","title":"भक्तिकाल: निर्गुण धारा","section":"साहित्य का इतिहास","summary":"भक्तिकाल (वि.सं. 1375–1700) में भक्ति की दो धाराएँ चलीं – निर्गुण और सगुण। निर्गुण धारा की दो शाखाएँ हैं – ज्ञानाश्रयी (संत काव्य), जिसके प्रमुख कवि कबीर और रैदास हैं, और प्रेमाश्रयी (सूफ़ी काव्य), जिसके प्रमुख कवि जायसी हैं।","nTerms":5},{"id":"bhakti-sagun","title":"भक्तिकाल: सगुण धारा","section":"साहित्य का इतिहास","summary":"सगुण धारा में ईश्वर के साकार रूप की उपासना हुई। इसकी दो शाखाएँ हैं – रामभक्ति (तुलसीदास) और कृष्णभक्ति (सूरदास, मीराबाई तथा अष्टछाप के कवि)।","nTerms":5},{"id":"patra-lekhan","title":"पत्र लेखन (औपचारिक और अनौपचारिक)","section":"लेखन","summary":"पत्र दो प्रकार के होते हैं – औपचारिक (प्रधानाचार्य, अधिकारी, संपादक आदि को) और अनौपचारिक (परिवार, मित्र आदि को)। दोनों का प्रारूप और भाषा-शैली भिन्न होती है।","nTerms":5},{"id":"anuchhed-lekhan","title":"अनुच्छेद लेखन","section":"लेखन","summary":"किसी विषय पर सीमित शब्दों में क्रमबद्ध और सुसंगठित विचार लिखना अनुच्छेद लेखन कहलाता है। इसमें एक ही केंद्रीय विचार होता है और वाक्य आपस में जुड़े रहते हैं।","nTerms":4},{"id":"punjabi-hindi-anuvad","title":"पंजाबी से हिंदी अनुवाद","section":"लेखन","summary":"किसी भाषा के कथन को दूसरी भाषा में अर्थ-सहित बदलना अनुवाद कहलाता है। पंजाबी और हिंदी की शब्दावली व वाक्य-रचना में समानता है, पर क्रिया-रूप, लिंग और कुछ शब्दों में अंतर होता है।","nTerms":4},{"id":"sankshepan","title":"संक्षेपीकरण","section":"लेखन","summary":"किसी विस्तृत गद्यांश के मुख्य भाव को कम शब्दों में, अपनी भाषा में प्रस्तुत करना संक्षेपीकरण है। इसमें मूल का अर्थ नहीं बदलना चाहिए और अनावश्यक बातें हटा दी जाती हैं।","nTerms":4}]},"history":{"syllabus":{"board":"CBSE","match":"textbook","books":["Themes in World History"],"reviewed":false},"chapters":[{"id":"writing-and-city-life","title":"Writing and City Life","section":"Early Societies","summary":"How the first cities and the first writing system arose in Mesopotamia, between the Tigris and Euphrates rivers, and what they tell us about trade, kingship, religion and knowledge.","nTerms":6},{"id":"empire-across-three-continents","title":"An Empire Across Three Continents","section":"Empires","summary":"The Roman Empire, which spread over Europe, North Africa and West Asia: its political system, army, economy, society and the causes of its later division and decline.","nTerms":5},{"id":"nomadic-empires","title":"Nomadic Empires","section":"Empires","summary":"The Mongol empire of Chinggis Khan and his successors: how a nomadic people of the Central Asian steppe built a vast empire, how it was governed and why it divided.","nTerms":5},{"id":"the-three-orders","title":"The Three Orders","section":"Changing Traditions","summary":"Feudal society in western Europe from about the ninth to the sixteenth century, divided into three orders: the clergy, the nobility and the peasantry, and how it changed with towns and crisis.","nTerms":6},{"id":"changing-cultural-traditions","title":"Changing Cultural Traditions","section":"Changing Traditions","summary":"The Renaissance in Europe (fourteenth to seventeenth century): humanism, art, printing, new ideas about the universe and the Reformation that challenged the authority of the Church.","nTerms":5},{"id":"displacing-indigenous-peoples","title":"Displacing Indigenous Peoples","section":"Towards Modernisation","summary":"How European settlers took over the lands of the native peoples of North America and Australia, and how these peoples lost their lands, lives and ways of life.","nTerms":5},{"id":"paths-to-modernisation","title":"Paths to Modernisation","section":"Towards Modernisation","summary":"How Japan and China responded to Western pressure in the nineteenth and twentieth centuries: Japan's Meiji reforms and rise as an imperial power, and China's reform, revolution and the rise of Communist rule.","nTerms":5}]},"historypb":{"syllabus":{"board":"PSEB","match":"textbook","books":["History of India (PSEB, Class 11)"],"note":"Follows the PSEB 2026–27 syllabus; written from the syllabus topics, not the PSEB book's own text.","reviewed":false},"chapters":[{"id":"indus-valley","title":"Indus Valley Civilization","section":"Ancient India","summary":"India's first urban civilization (mature phase c. 2600–1900 BCE): its main sites, town planning, economy, crafts, trade and the debated causes of its decline.","nTerms":4},{"id":"indo-aryans","title":"The Indo-Aryans","section":"Ancient India","summary":"The Vedic age: the Rig Vedic and Later Vedic periods, their literature, society, polity, economy and religion.","nTerms":4},{"id":"buddhism-jainism","title":"Buddhism and Jainism","section":"Ancient India","summary":"The rise of two new religions in the 6th century BCE: the lives and teachings of Mahavira and Gautama Buddha, their spread and their legacy.","nTerms":4},{"id":"mauryas","title":"The Mauryas (Ashoka's Dhamma)","section":"Ancient India","summary":"The first empire to unite most of the subcontinent: Chandragupta Maurya, his administration, Ashoka and his Dhamma, and the end of the empire.","nTerms":4},{"id":"guptas","title":"The Age of the Guptas","section":"Ancient India","summary":"The Gupta empire (4th–6th centuries CE): its great rulers, administration, economy, and achievements in literature, science, art and architecture.","nTerms":4},{"id":"vardhanas","title":"The Vardhanas and their Times","section":"Ancient India","summary":"Harsha of Kanauj (606–647 CE), his administration and patronage, accounts of Xuanzang and Bana, and the main kingdoms of the South: Chalukyas, Pallavas and Cholas.","nTerms":4},{"id":"rajputs","title":"The Rajputs","section":"Medieval India","summary":"The Rajput kingdoms of the 8th–12th centuries, their society and culture, and their struggle against early Turkish invaders.","nTerms":4},{"id":"delhi-sultanate","title":"The Sultanate of Delhi","section":"Medieval India","summary":"The Delhi Sultanate (1206–1526): its five dynasties, major rulers, administration, and architecture.","nTerms":4},{"id":"bahmani-vijayanagar","title":"Kingdoms of the South: Bahmani and Vijayanagar","section":"Medieval India","summary":"The Bahmani kingdom (1347) and the Vijayanagar empire (1336) in the Deccan and the south: rise, rulers, administration, culture and decline.","nTerms":4},{"id":"bhakti-saints","title":"Socio-religious Movements: Vaishnava Bhakti and the Saints","section":"Medieval India","summary":"The Bhakti and Sufi movements in medieval India: their ideas, the main saints and their effect on society.","nTerms":4},{"id":"guru-nanak-sikhism","title":"Sri Guru Nanak Dev Ji and the Foundation of Sikhism","section":"Medieval India","summary":"The life and teachings of Sri Guru Nanak Dev Ji, the development of Sikhism under the Gurus (1539–1605), its transformation (1606–1699) and the creation of the Khalsa.","nTerms":4},{"id":"mughal-establishment","title":"Establishment of the Mughal Empire","section":"Medieval India","summary":"Babur's victory at Panipat (1526), Humayun's struggle with Sher Shah and the Afghans, and Akbar's recovery of the empire in 1556.","nTerms":4},{"id":"mughal-polity","title":"Mughal Polity and Administration","section":"Medieval India","summary":"Mughal ideas of kingship, the central and provincial administration, the mansabdari system and land revenue, mainly under Akbar.","nTerms":4},{"id":"marathas","title":"Rise of New Powers in the South: the Marathas","section":"Medieval India","summary":"Shivaji and the foundation of the Maratha state, his administration, and the later Maratha power under the Peshwas until 1761.","nTerms":4},{"id":"rise-of-sikhs","title":"Rise of New Powers in the North: the Sikhs","section":"Medieval India","summary":"Banda Singh Bahadur, the eighteenth-century struggle against the Mughals and Afghans, the Dal Khalsa and the rise of the Sikh misls.","nTerms":4},{"id":"ranjit-singh","title":"Maharaja Ranjit Singh","section":"Modern India","summary":"Maharaja Ranjit Singh (1780–1839): his rise from the Sukerchakia misl, conquests, relations with the British, administration and character.","nTerms":4},{"id":"europeans","title":"Advent of the Europeans","section":"Modern India","summary":"The coming of the Portuguese, Dutch, English and French, their rivalry, and the rise of the English East India Company.","nTerms":4},{"id":"british-expansion","title":"Expansion and Consolidation of British Rule","section":"Modern India","summary":"From Plassey (1757) and Buxar (1764) to the annexation of the Punjab (1849): wars, subsidiary alliances and the doctrine of lapse.","nTerms":4},{"id":"social-economic-changes","title":"Social and Economic Changes under British Rule","section":"Modern India","summary":"How British rule changed land revenue, agriculture, handicrafts, communications, education and society.","nTerms":4},{"id":"socio-religious-movements","title":"Socio-religious Movements","section":"Modern India","summary":"Nineteenth-century reform movements: Brahmo Samaj, Arya Samaj, the Aligarh movement, and the Nirankari, Kuka (Namdhari) and Singh Sabha movements among the Sikhs.","nTerms":4},{"id":"political-consciousness","title":"Political Consciousness and the Struggle for Representative Government","section":"Modern India","summary":"From the Revolt of 1857 to the Indian National Congress (1885), the partition of Bengal, Home Rule, constitutional reforms and Jallianwala Bagh (1919).","nTerms":4},{"id":"towards-freedom","title":"Towards Freedom","section":"Modern India","summary":"Gandhian movements, the Quit India Movement (1942), the INA, the Cabinet Mission, Partition and the transfer of power on 15 August 1947.","nTerms":4}]},"maths":{"syllabus":{"board":"CBSE","match":"textbook","books":["Mathematics"],"reviewed":false},"chapters":[{"id":"sets","title":"Sets","section":"Sets and Functions","summary":"What a set is, roster and set-builder forms, types of sets, subsets and intervals, Venn diagrams, and the operations of union, intersection, difference and complement with De Morgan's laws.","nTerms":6},{"id":"relations-and-functions","title":"Relations and Functions","section":"Sets and Functions","summary":"Ordered pairs and Cartesian products, relations with their domain and range, functions as special relations, standard real functions with their graphs, and the algebra of real functions.","nTerms":6},{"id":"trigonometric-functions","title":"Trigonometric Functions","section":"Sets and Functions","summary":"Measuring angles in degrees and radians, trigonometric functions of real numbers through the unit circle, their signs, domains, ranges and periods, and the sum, difference, multiple-angle and transformation formulas.","nTerms":6},{"id":"complex-numbers-and-quadratic-equations","title":"Complex Numbers and Quadratic Equations","section":"Algebra","summary":"Why we need the number i = √−1, the algebra of complex numbers, modulus and conjugate, the Argand plane, and solving quadratic equations whose discriminant is negative.","nTerms":6},{"id":"linear-inequalities","title":"Linear Inequalities","section":"Algebra","summary":"Inequalities in one variable, the rules for solving them, showing the solution on the number line, and word problems that lead to linear inequalities.","nTerms":5},{"id":"permutations-and-combinations","title":"Permutations and Combinations","section":"Algebra","summary":"The fundamental principle of counting, factorial notation, permutations (arrangements) with and without repetition, and combinations (selections), with typical problems on words, numbers and committees.","nTerms":5},{"id":"binomial-theorem","title":"Binomial Theorem","section":"Algebra","summary":"Expanding (a + b)ⁿ for a positive integer n using binomial coefficients and Pascal's triangle, with applications such as evaluating large powers and proving divisibility, plus general and middle terms for entrance-exam practice.","nTerms":5},{"id":"sequences-and-series","title":"Sequences and Series","section":"Algebra","summary":"Sequences and series, arithmetic and geometric progressions, the nth term and sum of a G.P. (including an infinite G.P.), arithmetic and geometric means with the A.M.–G.M. inequality, and standard sums of special series.","nTerms":6},{"id":"straight-lines","title":"Straight Lines","section":"Coordinate Geometry","summary":"Slope of a line, conditions for parallel and perpendicular lines, the angle between two lines, the various forms of the equation of a line, and the distance of a point from a line.","nTerms":6},{"id":"conic-sections","title":"Conic Sections","section":"Coordinate Geometry","summary":"Circles, parabolas, ellipses and hyperbolas as sections of a double cone, with their standard equations, foci, vertices, axes, eccentricity and latus rectum.","nTerms":6},{"id":"introduction-to-three-dimensional-geometry","title":"Introduction to Three Dimensional Geometry","section":"Coordinate Geometry","summary":"Locating points in space with three mutually perpendicular axes: coordinate planes, octants, coordinates of a point, and the distance between two points.","nTerms":5},{"id":"limits-and-derivatives","title":"Limits and Derivatives","section":"Calculus","summary":"The intuitive idea of a limit, left- and right-hand limits, the algebra of limits and standard limits (including trigonometric ones), and the derivative from first principles with the rules for sums, products and quotients.","nTerms":6},{"id":"statistics","title":"Statistics","section":"Statistics and Probability","summary":"Measures of dispersion: range, mean deviation about the mean and median, and variance and standard deviation for ungrouped, discrete and continuous frequency data.","nTerms":6},{"id":"probability","title":"Probability","section":"Statistics and Probability","summary":"Random experiments, sample spaces and events, the algebra of events, mutually exclusive and exhaustive events, and the axiomatic approach to probability with the addition rule.","nTerms":6}]},"physics":{"syllabus":{"board":"CBSE","match":"textbook","books":["Physics Part I","Physics Part II"],"reviewed":false},"chapters":[{"id":"units-and-measurement","title":"Units and Measurement","section":"Mechanics","summary":"Physics rests on measurement. This chapter covers the SI system of base and derived units, the rules for significant figures and rounding off, and dimensional analysis, which is used to check equations, convert units and deduce relations between quantities.","nTerms":6},{"id":"motion-in-a-straight-line","title":"Motion in a Straight Line","section":"Mechanics","summary":"Describes motion along a straight line using position, displacement, velocity and acceleration, their graphs, the kinematic equations for uniformly accelerated motion, free fall under gravity and relative velocity.","nTerms":6},{"id":"motion-in-a-plane","title":"Motion in a Plane","section":"Mechanics","summary":"Extends kinematics to two dimensions using vectors: addition, subtraction and resolution of vectors, motion with constant acceleration in a plane, projectile motion and uniform circular motion.","nTerms":6},{"id":"laws-of-motion","title":"Laws of Motion","section":"Mechanics","summary":"Newton's three laws link force and motion. The chapter covers inertia, momentum and impulse, conservation of momentum, equilibrium of a particle, friction and the dynamics of circular motion, including vehicles on level and banked roads.","nTerms":6},{"id":"work-energy-and-power","title":"Work, Energy and Power","section":"Mechanics","summary":"Introduces the scalar product, work done by constant and variable forces, the work-energy theorem, kinetic and potential energy (including the energy of a spring), conservation of mechanical energy, power, and elastic and inelastic collisions.","nTerms":6},{"id":"system-of-particles-and-rotational-motion","title":"System of Particles and Rotational Motion","section":"Mechanics","summary":"Deals with extended bodies: the centre of mass and its motion, the vector product, torque and angular momentum, equilibrium of rigid bodies, moment of inertia and the dynamics of rotation about a fixed axis.","nTerms":6},{"id":"gravitation","title":"Gravitation","section":"Mechanics","summary":"Covers Kepler's laws of planetary motion, Newton's universal law of gravitation, the variation of g with height and depth, gravitational potential energy and potential, escape speed, and the speed and energy of earth satellites.","nTerms":6},{"id":"mechanical-properties-of-solids","title":"Mechanical Properties of Solids","section":"Properties of Matter","summary":"Explains the elastic behaviour of solids: stress and strain, Hooke's law, the stress–strain curve, Young's modulus, shear modulus, bulk modulus and Poisson's ratio, and how elasticity is used in engineering design.","nTerms":6},{"id":"mechanical-properties-of-fluids","title":"Mechanical Properties of Fluids","section":"Properties of Matter","summary":"Studies fluids at rest and in motion: pressure and Pascal's law, streamline flow, the equation of continuity and Bernoulli's principle, viscosity and Stokes' law, and surface tension with its effects on drops, bubbles and capillary rise.","nTerms":6},{"id":"thermal-properties-of-matter","title":"Thermal Properties of Matter","section":"Properties of Matter","summary":"Covers temperature scales and the ideal gas equation, thermal expansion of solids, liquids and gases, specific heat and calorimetry, change of state and latent heat, and heat transfer by conduction, convection and radiation, with Newton's law of cooling.","nTerms":6},{"id":"thermodynamics","title":"Thermodynamics","section":"Heat and Thermodynamics","summary":"Deals with heat, work and internal energy: the zeroth and first laws, specific heats of gases, thermodynamic processes (isothermal, adiabatic, isochoric, isobaric and cyclic), the second law, reversible and irreversible processes, and the Carnot engine.","nTerms":6},{"id":"kinetic-theory","title":"Kinetic Theory","section":"Heat and Thermodynamics","summary":"Explains the behaviour of gases in terms of moving molecules: the gas laws, assumptions of kinetic theory, pressure of an ideal gas, kinetic interpretation of temperature and rms speed, the law of equipartition of energy, specific heats and mean free path.","nTerms":6},{"id":"oscillations","title":"Oscillations","section":"Oscillations and Waves","summary":"Studies periodic and oscillatory motion, especially simple harmonic motion (SHM): its displacement, velocity and acceleration, its link with uniform circular motion, the force law, energy in SHM, and the spring–mass system and simple pendulum.","nTerms":6},{"id":"waves","title":"Waves","section":"Oscillations and Waves","summary":"Describes mechanical waves: transverse and longitudinal waves, the equation of a travelling wave, wave speed on a string and in a fluid (Newton's formula and Laplace's correction), superposition, reflection, standing waves in strings and pipes, and beats.","nTerms":6}]},"polsci":{"syllabus":{"board":"CBSE","match":"textbook","books":["Indian Constitution at Work","Political Theory"],"reviewed":false},"chapters":[{"id":"constitution-why-and-how","title":"Constitution: Why and How?","section":"Indian Constitution at Work","summary":"Why a society needs a constitution, what gives a constitution authority, and how India's Constituent Assembly drafted the Constitution between 1946 and 1949, drawing on the national movement and other constitutions.","nTerms":6},{"id":"rights-in-the-indian-constitution","title":"Rights in the Indian Constitution","section":"Indian Constitution at Work","summary":"The Fundamental Rights in Part III of the Constitution, the writs that protect them, the Directive Principles of State Policy and the Fundamental Duties.","nTerms":6},{"id":"election-and-representation","title":"Election and Representation","section":"Indian Constitution at Work","summary":"How representatives are elected in India: the First Past the Post and Proportional Representation systems, why India chose FPTP, reserved constituencies, universal adult franchise and the Election Commission.","nTerms":6},{"id":"executive","title":"Executive","section":"Indian Constitution at Work","summary":"The executive branch: types of executive, the President and Vice-President, the Prime Minister and Council of Ministers, and the permanent executive or bureaucracy.","nTerms":6},{"id":"legislature","title":"Legislature","section":"Indian Constitution at Work","summary":"Parliament as the central law-making body: the composition and powers of the Lok Sabha and Rajya Sabha, how a bill becomes a law, how Parliament controls the executive, and the anti-defection law.","nTerms":6},{"id":"judiciary","title":"Judiciary","section":"Indian Constitution at Work","summary":"Why the judiciary must be independent, how judges are appointed and removed, the structure and jurisdiction of the courts, judicial activism and PIL, and judicial review.","nTerms":6},{"id":"federalism","title":"Federalism","section":"Indian Constitution at Work","summary":"How the Constitution divides power between the Union and the states, why it created a strong Centre, the conflicts in Centre–state relations, and special provisions for some states.","nTerms":6},{"id":"local-governments","title":"Local Governments","section":"Indian Constitution at Work","summary":"Why local government matters, how it grew in India, the 73rd and 74th Amendments that created Panchayati Raj and urban local bodies, and the problems they face.","nTerms":6},{"id":"constitution-as-a-living-document","title":"Constitution as a Living Document","section":"Indian Constitution at Work","summary":"How the Constitution has adapted over time: the amendment procedure in Article 368, why so many amendments were made, the contentious amendments of the 1970s, and the basic structure doctrine.","nTerms":6},{"id":"philosophy-of-the-constitution","title":"The Philosophy of the Constitution","section":"Indian Constitution at Work","summary":"The moral vision behind the Constitution: individual freedom, social justice, respect for diversity, secularism, universal franchise and federalism, along with its procedural achievements, criticisms and limitations.","nTerms":6},{"id":"political-theory-an-introduction","title":"Political Theory: An Introduction","section":"Political Theory","summary":"What politics is, what political theory studies, how great thinkers have shaped ideas like freedom and equality, and why students and citizens should study political theory.","nTerms":6},{"id":"freedom","title":"Freedom","section":"Political Theory","summary":"The meaning of freedom as both absence of constraints and presence of conditions for self-development, swaraj, sources of constraints, Mill's harm principle, negative and positive liberty, and freedom of expression.","nTerms":6},{"id":"equality","title":"Equality","section":"Political Theory","summary":"Why equality matters, what it means, its political, social and economic dimensions, how different ideologies view it, and the ways of promoting equality.","nTerms":6},{"id":"social-justice","title":"Social Justice","section":"Political Theory","summary":"What justice means, the three principles of justice, just distribution, John Rawls' theory of justice as fairness, and the debate on how to pursue social justice.","nTerms":6},{"id":"rights","title":"Rights","section":"Political Theory","summary":"What rights are, where they come from, how they become legal rights, the different kinds of rights, and the responsibilities that come with them.","nTerms":6},{"id":"citizenship","title":"Citizenship","section":"Political Theory","summary":"Citizenship as full and equal membership of a political community, citizenship in India, struggles for equal rights, refugees and stateless people, and the ideas of universal and global citizenship.","nTerms":6},{"id":"nationalism","title":"Nationalism","section":"Political Theory","summary":"Nationalism as a political force, what makes a nation, the claim to national self-determination and its problems, and how nationalism can accommodate pluralism.","nTerms":6},{"id":"secularism","title":"Secularism","section":"Political Theory","summary":"What secularism means, inter- and intra-religious domination, the secular state, the Western and Indian models of secularism, and the criticisms of Indian secularism.","nTerms":6}]},"polscipb":{"syllabus":{"board":"PSEB","match":"textbook","books":["Political Science (PSEB, Class 11)"],"note":"Follows the PSEB 2026–27 syllabus; written from the syllabus topics, not the PSEB book's own text.","reviewed":false},"chapters":[{"id":"political-science-meaning-scope-importance","title":"Political Science: Meaning, Scope and Importance","section":"Political Theory","summary":"What Political Science studies, how its scope is described, and why it matters for citizens and for understanding government.","nTerms":5},{"id":"law-and-justice","title":"Law (meaning, kinds, sources) and Justice","section":"Political Theory","summary":"The meaning of law, its main kinds and sources, and the idea of justice.","nTerms":6},{"id":"liberty-and-equality","title":"Liberty and Equality","section":"Political Theory","summary":"The meaning and kinds of liberty and equality, and how the two relate to each other.","nTerms":6},{"id":"citizenship","title":"Citizenship (acquiring and losing, good citizen)","section":"Political Theory","summary":"Who a citizen is, how citizenship is acquired and lost, and the qualities of a good citizen.","nTerms":5},{"id":"the-state","title":"The State (elements; state vs government)","section":"Political Theory","summary":"The definition of the state, its four elements, and how the state differs from government.","nTerms":6},{"id":"forms-of-government","title":"Forms of Government","section":"Political Theory","summary":"Main classifications of government: democracy and dictatorship, unitary and federal, parliamentary and presidential.","nTerms":6},{"id":"legislature","title":"Legislature","section":"Organs of Government","summary":"The role, functions and structure (unicameral and bicameral) of the legislature, the law-making organ of government.","nTerms":5},{"id":"executive","title":"Executive","section":"Organs of Government","summary":"The executive organ: its meaning, kinds (political and permanent) and functions.","nTerms":5},{"id":"judiciary","title":"Judiciary","section":"Organs of Government","summary":"The role of the judiciary, its independence, judicial review and the Indian judicial structure.","nTerms":5},{"id":"preamble-and-salient-features","title":"Preamble and Salient Features of the Indian Constitution","section":"Indian Constitution","summary":"The making of the Constitution, the Preamble and the main features of the Indian Constitution.","nTerms":6},{"id":"rights-and-fundamental-rights","title":"Rights and Fundamental Rights","section":"Indian Constitution","summary":"The meaning of rights and the six Fundamental Rights in Part III of the Indian Constitution.","nTerms":6},{"id":"duties-and-fundamental-duties","title":"Duties and Fundamental Duties","section":"Indian Constitution","summary":"The relation between rights and duties and the Fundamental Duties in Article 51A of the Constitution.","nTerms":5},{"id":"directive-principles-of-state-policy","title":"Directive Principles of State Policy (and difference from Fundamental Rights)","section":"Indian Constitution","summary":"The Directive Principles in Part IV (Arts 36–51), their classification and how they differ from Fundamental Rights.","nTerms":6},{"id":"indian-federation-centre-state-relations","title":"Nature of the Indian Federation and Centre–State Relations","section":"Indian Constitution","summary":"The federal features of India, the unitary bias, and the legislative, administrative and financial relations between the Centre and states.","nTerms":6},{"id":"union-government-parliament","title":"Union Government: Parliament","section":"Union Government","summary":"The composition, powers and working of the Indian Parliament: Lok Sabha, Rajya Sabha and how a bill becomes law.","nTerms":6},{"id":"union-government-executive","title":"Union Government: Executive (President, PM, Council of Ministers)","section":"Union Government","summary":"The President, Vice-President, Prime Minister and Council of Ministers of the Union and their powers.","nTerms":6},{"id":"state-government-legislature","title":"State Government: Legislature","section":"State Government","summary":"The composition, powers and functions of the state Legislative Assembly and Legislative Council.","nTerms":5},{"id":"state-government-executive","title":"State Government: Executive (Governor, CM)","section":"State Government","summary":"The Governor, Chief Minister and state Council of Ministers: appointment, powers and relationships.","nTerms":5},{"id":"the-supreme-court","title":"The Supreme Court","section":"Judiciary in India","summary":"The composition, jurisdiction and role of the Supreme Court of India, the apex court and guardian of the Constitution.","nTerms":6},{"id":"the-high-court","title":"The High Court","section":"Judiciary in India","summary":"The composition, powers and jurisdiction of the High Courts, including the Punjab and Haryana High Court.","nTerms":5}]},"punjabi":{"syllabus":{"board":"CBSE","match":"textbook","books":["ਲਾਜ਼ਮੀ ਪੰਜਾਬੀ-11"],"note":"ਵਿਆਕਰਨ ਅਤੇ ਲੇਖ ਰਚਨਾ, ਨਾਲ ਹੀ ਪੰਜਾਬ ਸਕੂਲ ਸਿੱਖਿਆ ਬੋਰਡ ਦੀ ਪੁਸਤਕ ਲਾਜ਼ਮੀ ਪੰਜਾਬੀ-11 ਦੇ ਪਾਠ ਅਤੇ ਲੋਕ-ਸਾਹਿਤ ਵਾਲਾ ਭਾਗ (ਲੋਕ-ਗੀਤ, ਬੁਝਾਰਤਾਂ ਅਤੇ ਲੋਕ-ਕਥਾਵਾਂ), ਸਭ ਆਪਣੇ ਸ਼ਬਦਾਂ ਵਿੱਚ ਸੰਖੇਪ।","reviewed":false},"chapters":[{"id":"gurmukhi-lipi","title":"ਗੁਰਮੁਖੀ ਲਿਪੀ ਦੀ ਬਣਤਰ","section":"ਭਾਸ਼ਾ ਬਾਰੇ ਜਾਣਕਾਰੀ","summary":"ਲਿਪੀ ਉਹ ਚਿੰਨ੍ਹ-ਪ੍ਰਣਾਲੀ ਹੈ ਜਿਸ ਰਾਹੀਂ ਬੋਲੀ ਨੂੰ ਲਿਖਿਆ ਜਾਂਦਾ ਹੈ। ਇਸ ਪਾਠ ਵਿੱਚ ਗੁਰਮੁਖੀ ਦੇ ਮੂਲ ਅੱਖਰ, ਲਗਾਂ, ਨਾਸਿਕ ਚਿੰਨ੍ਹ ਅਤੇ ਪੈਰ ਬਿੰਦੀ ਵਾਲੇ ਅੱਖਰਾਂ ਦੀ ਜਾਣਕਾਰੀ ਹੈ।","nTerms":6},{"id":"punjabi-upbhasha","title":"ਪੰਜਾਬੀ ਦੀਆਂ ਉਪ-ਭਾਸ਼ਾਵਾਂ","section":"ਭਾਸ਼ਾ ਬਾਰੇ ਜਾਣਕਾਰੀ","summary":"ਇੱਕ ਭਾਸ਼ਾ ਦੇ ਅੰਦਰ ਖੇਤਰ ਅਨੁਸਾਰ ਬੋਲੇ ਜਾਣ ਵਾਲੇ ਰੂਪਾਂ ਨੂੰ ਉਪ-ਭਾਸ਼ਾਵਾਂ ਕਹਿੰਦੇ ਹਨ। ਇਸ ਪਾਠ ਵਿੱਚ ਪੰਜਾਬੀ ਦੀਆਂ ਚਾਰ ਮੁੱਖ ਉਪ-ਭਾਸ਼ਾਵਾਂ ਅਤੇ ਮਿਆਰੀ ਭਾਸ਼ਾ ਦਾ ਫ਼ਰਕ ਹੈ।","nTerms":6},{"id":"dhuni-viunta","title":"ਧੁਨੀ ਵਿਉਂਤ: ਸਵਰ, ਵਿਅੰਜਨ, ਸੁਰ","section":"ਵਿਆਕਰਨ","summary":"ਬੋਲੀ ਦੀ ਸਭ ਤੋਂ ਛੋਟੀ ਆਵਾਜ਼ ਨੂੰ ਧੁਨੀ ਕਹਿੰਦੇ ਹਨ। ਇਸ ਪਾਠ ਵਿੱਚ ਸਵਰ, ਵਿਅੰਜਨ, ਵਿਅੰਜਨਾਂ ਦੇ ਵਰਗ ਅਤੇ ਸੁਰ ਦੀ ਜਾਣਕਾਰੀ ਹੈ।","nTerms":5},{"id":"shabad-banavat","title":"ਸ਼ਬਦ ਬਣਤਰ: ਅਗੇਤਰ, ਪਿਛੇਤਰ, ਸਮਾਸ","section":"ਵਿਆਕਰਨ","summary":"ਮੂਲ ਸ਼ਬਦ ਨਾਲ ਅਗੇਤਰ ਜਾਂ ਪਿਛੇਤਰ ਲੱਗ ਕੇ ਨਵੇਂ ਸ਼ਬਦ ਬਣਦੇ ਹਨ, ਅਤੇ ਦੋ ਸ਼ਬਦ ਮਿਲ ਕੇ ਸਮਾਸ ਬਣਾਉਂਦੇ ਹਨ। ਇਸ ਪਾਠ ਵਿੱਚ ਇਹਨਾਂ ਦੀ ਪਛਾਣ ਅਤੇ ਉਦਾਹਰਨਾਂ ਹਨ।","nTerms":5},{"id":"muhavre-akhaan","title":"ਮੁਹਾਵਰੇ ਅਤੇ ਅਖਾਣ","section":"ਵਿਆਕਰਨ","summary":"ਮੁਹਾਵਰਾ ਸ਼ਬਦਾਂ ਦਾ ਅਜਿਹਾ ਜੋੜ ਹੈ ਜਿਸ ਦਾ ਅਰਥ ਲਾਖਣਿਕ ਹੁੰਦਾ ਹੈ, ਅਤੇ ਅਖਾਣ ਲੋਕ-ਤਜਰਬੇ ਦਾ ਪੂਰਾ ਵਾਕ ਹੁੰਦਾ ਹੈ। ਇਸ ਪਾਠ ਵਿੱਚ ਦੋਹਾਂ ਦੀ ਪਛਾਣ ਅਤੇ ਵਰਤੋਂ ਹੈ।","nTerms":5},{"id":"lekh-rachna","title":"ਲੇਖ ਰਚਨਾ","section":"ਲੇਖ ਰਚਨਾ","summary":"ਕਿਸੇ ਵਿਸ਼ੇ ਉੱਤੇ ਤਰਤੀਬ ਨਾਲ ਅਤੇ ਵਿਸਥਾਰ ਨਾਲ ਵਿਚਾਰ ਕਈ ਪੈਰਿਆਂ ਵਿੱਚ ਲਿਖਣਾ ਲੇਖ ਰਚਨਾ ਹੈ। ਇਸ ਪਾਠ ਵਿੱਚ ਤਿਆਰੀ, ਢਾਂਚਾ ਅਤੇ ਭਾਸ਼ਾ ਦੇ ਨਿਯਮ ਹਨ।","nTerms":5},{"id":"daftari-chitthi","title":"ਦਫ਼ਤਰੀ ਚਿੱਠੀ","section":"ਲੇਖ ਰਚਨਾ","summary":"ਦਫ਼ਤਰੀ ਚਿੱਠੀ ਕਿਸੇ ਦਫ਼ਤਰ ਜਾਂ ਅਧਿਕਾਰੀ ਨੂੰ ਕੰਮ ਦੇ ਸਿਲਸਿਲੇ ਵਿੱਚ ਲਿਖੀ ਜਾਂਦੀ ਹੈ। ਇਸ ਪਾਠ ਵਿੱਚ ਚਿੱਠੀ ਦਾ ਢਾਂਚਾ, ਭਾਸ਼ਾ ਅਤੇ ਵਿਸ਼ਾ ਲਿਖਣ ਦਾ ਢੰਗ ਹੈ।","nTerms":5},{"id":"sankhep-rachna","title":"ਸੰਖੇਪ ਰਚਨਾ","section":"ਲੇਖ ਰਚਨਾ","summary":"ਕਿਸੇ ਲੰਮੇ ਗੱਦ-ਅੰਸ਼ ਦੇ ਮੁੱਖ ਵਿਚਾਰ ਆਪਣੇ ਸ਼ਬਦਾਂ ਵਿੱਚ ਥੋੜ੍ਹੇ ਸ਼ਬਦਾਂ ਵਿੱਚ ਲਿਖਣਾ ਸੰਖੇਪ ਰਚਨਾ ਹੈ। ਇਸ ਪਾਠ ਵਿੱਚ ਸ਼ਬਦ-ਸੀਮਾ, ਕੀ ਛੱਡਣਾ ਅਤੇ ਕੀ ਰੱਖਣਾ, ਅਤੇ ਸ਼ੈਲੀ ਦੀ ਜਾਣਕਾਰੀ ਹੈ।","nTerms":5},{"id":"anuvad-ang-pan","title":"ਅੰਗਰੇਜ਼ੀ ਤੋਂ ਪੰਜਾਬੀ ਵਿੱਚ ਅਨੁਵਾਦ","section":"ਲਾਜ਼ਮੀ ਪੰਜਾਬੀ","summary":"ਇਸ ਅਧਿਆਇ ਦੇ ਦੋ ਭਾਗ ਹਨ। ਪਹਿਲੇ ਵਿੱਚ ਦਫ਼ਤਰੀ ਅਤੇ ਵੱਖ-ਵੱਖ ਵਿਸ਼ਿਆਂ ਦੀ ਤਕਨੀਕੀ ਸ਼ਬਦਾਵਲੀ ਦੇ ਅੰਗਰੇਜ਼ੀ-ਪੰਜਾਬੀ ਰੂਪ ਹਨ; ਦੂਜੇ ਵਿੱਚ ਬੈਂਕ, ਰੇਲਵੇ, ਡਾਕ, ਕੰਪਿਊਟਰ ਅਤੇ ਬੀਮਾ-ਸੇਵਾਵਾਂ ਨਾਲ ਜੁੜੇ ਵਾਕਾਂ ਦਾ ਪੰਜਾਬੀ ਅਨੁਵਾਦ ਹੈ।","nTerms":6},{"id":"patar-sampadak","title":"ਅਖ਼ਬਾਰ ਦੇ ਸੰਪਾਦਕ ਨੂੰ ਪੱਤਰ","section":"ਲਾਜ਼ਮੀ ਪੰਜਾਬੀ","summary":"ਪਾਠਕ ਕਿਸੇ ਮਸਲੇ ਜਾਂ ਘਟਨਾ ਬਾਰੇ ਆਪਣੀ ਰਾਇ ਅਖ਼ਬਾਰ ਦੇ ਸੰਪਾਦਕ ਨੂੰ ਪੱਤਰ ਲਿਖ ਕੇ ਭੇਜਦੇ ਹਨ। ਇਸ ਅਧਿਆਇ ਵਿੱਚ ਪੱਤਰਾਂ ਦਾ ਮਹੱਤਵ, ਰੂਪ-ਰੇਖਾ ਅਤੇ ਸੜਕੀ ਦੁਰਘਟਨਾ, ਇਮਾਨਦਾਰੀ ਅਤੇ ਮਦਦ ਵਰਗੇ ਵਿਸ਼ਿਆਂ ਦੇ ਨਮੂਨੇ ਹਨ।","nTerms":5},{"id":"ishtihar-sadda-patar","title":"ਇਸ਼ਤਿਹਾਰ / ਸੱਦਾ-ਪੱਤਰ","section":"ਲਾਜ਼ਮੀ ਪੰਜਾਬੀ","summary":"ਇਸ਼ਤਿਹਾਰ ਰਾਹੀਂ ਕੋਈ ਸੂਚਨਾ ਛੇਤੀ ਬਹੁਤ ਲੋਕਾਂ ਤਕ ਪਹੁੰਚਾਈ ਜਾਂਦੀ ਹੈ, ਜਿਵੇਂ ਵਿਆਹ, ਨਾਂ ਬਦਲੀ, ਵਿਕਰੀ ਜਾਂ ਕਿਰਾਏ ਬਾਰੇ। ਸੱਦਾ-ਪੱਤਰ ਖ਼ੁਸ਼ੀ ਜਾਂ ਗ਼ਮੀ ਦੇ ਸਮਾਗਮ ਲਈ ਬੁਲਾਵਾ ਦੇਣ ਵਾਲਾ ਪੱਤਰ ਹੈ।","nTerms":6},{"id":"paira-rachna-lp11","title":"ਪੈਰਾ-ਰਚਨਾ","section":"ਲਾਜ਼ਮੀ ਪੰਜਾਬੀ","summary":"ਪੈਰਾ-ਰਚਨਾ ਲੇਖ-ਰਚਨਾ ਦਾ ਇੱਕ ਮਹੱਤਵਪੂਰਨ ਅੰਗ ਹੈ, ਜਿਸ ਵਿੱਚ ਕਿਸੇ ਵਿਸ਼ੇ, ਘਟਨਾ ਜਾਂ ਸੰਕਲਪ ਬਾਰੇ ਲਗਭਗ 150 ਸ਼ਬਦਾਂ ਵਿੱਚ ਸੰਖੇਪ ਅਤੇ ਸੰਪੂਰਨ ਲਿਖਤ ਤਿਆਰ ਕੀਤੀ ਜਾਂਦੀ ਹੈ। ਪੁਸਤਕ ਵਿੱਚ 'ਘਰ ਤੇ ਰੁੱਖ', 'ਸਫ਼ਰ ਕਰਨਾ', 'ਸਲੀਕਾ', 'ਮਨੋਰੰਜਨ' ਵਰਗੇ ਵਿਸ਼ਿਆਂ ਉੱਤੇ ਨਮੂਨੇ ਹਨ।","nTerms":5},{"id":"muhavre-pseb11","title":"ਮੁਹਾਵਰੇ","section":"ਲਾਜ਼ਮੀ ਪੰਜਾਬੀ","summary":"ਮੁਹਾਵਰੇ ਭਾਸ਼ਾ ਦੀ ਅਮੀਰੀ ਅਤੇ ਪ੍ਰਗਟਾਅ-ਸ਼ਕਤੀ ਦੀ ਜਿੰਦ-ਜਾਨ ਹਨ। ਇਸ ਅਧਿਆਇ ਵਿੱਚ ਮੁਹਾਵਰਿਆਂ ਦਾ ਮਹੱਤਵ ਅਤੇ ਅਰਥਾਂ ਸਮੇਤ ਚੋਣਵੇਂ ਮੁਹਾਵਰੇ ਵਾਕਾਂ ਵਿੱਚ ਵਰਤ ਕੇ ਦਿੱਤੇ ਗਏ ਹਨ।","nTerms":6},{"id":"lp11-lok-sahit","title":"ਪੰਜਾਬੀ ਲੋਕ-ਸਾਹਿਤ: ਜਾਣ-ਪਛਾਣ","section":"ਲਾਜ਼ਮੀ ਪੰਜਾਬੀ: ਲੋਕ-ਸਾਹਿਤ","summary":"ਇਸ ਭਾਗ ਵਿੱਚ ਦੱਸਿਆ ਗਿਆ ਹੈ ਕਿ ਲੋਕ-ਸਾਹਿਤ ਕੀ ਹੁੰਦਾ ਹੈ, ਇਹ ਵਿਸ਼ਿਸ਼ਟ ਸਾਹਿਤ ਤੋਂ ਕਿਵੇਂ ਵੱਖਰਾ ਹੈ ਅਤੇ ਪਾਠ-ਪੁਸਤਕ ਵਿੱਚ ਲੋਕ-ਗੀਤਾਂ ਤੇ ਲੋਕ-ਕਥਾਵਾਂ ਦੀਆਂ ਕਿਹੜੀਆਂ ਵੰਨਗੀਆਂ ਸ਼ਾਮਲ ਹਨ।","nTerms":5},{"id":"lp11-suhag","title":"ਸੁਹਾਗ","section":"ਲਾਜ਼ਮੀ ਪੰਜਾਬੀ: ਲੋਕ-ਸਾਹਿਤ","summary":"ਸੁਹਾਗ ਕੁੜੀ ਦੇ ਵਿਆਹ ਵੇਲੇ ਉਸ ਦੇ ਘਰ ਇਸਤਰੀਆਂ ਵੱਲੋਂ ਗਾਏ ਜਾਣ ਵਾਲੇ ਲੋਕ-ਗੀਤ ਹਨ, ਜਿਨ੍ਹਾਂ ਵਿੱਚ ਧੀ ਦੇ ਚਾਅ, ਬਾਬਲ ਦਾ ਮੋਹ ਅਤੇ ਪੇਕੇ ਘਰ ਨੂੰ ਛੱਡਣ ਦਾ ਉਦਰੇਵਾਂ ਮਿਲਦਾ ਹੈ।","nTerms":5},{"id":"lp11-ghodian","title":"ਘੋੜੀਆਂ","section":"ਲਾਜ਼ਮੀ ਪੰਜਾਬੀ: ਲੋਕ-ਸਾਹਿਤ","summary":"ਘੋੜੀਆਂ ਮੁੰਡੇ ਦੇ ਵਿਆਹ ਵੇਲੇ ਉਸ ਦੇ ਘਰ ਇਸਤਰੀਆਂ ਵੱਲੋਂ ਗਾਏ ਜਾਂਦੇ ਲੋਕ-ਗੀਤ ਹਨ, ਜਿਨ੍ਹਾਂ ਵਿੱਚ ਲਾੜੇ ਦੀ ਸ਼ਾਨ, ਉਸ ਦੇ ਖ਼ਾਨਦਾਨ ਦੀ ਵਡਿਆਈ ਅਤੇ ਸ਼ੁਭ ਕਾਮਨਾਵਾਂ ਹੁੰਦੀਆਂ ਹਨ।","nTerms":5},{"id":"lp11-sithnian","title":"ਸਿੱਠਣੀਆਂ","section":"ਲਾਜ਼ਮੀ ਪੰਜਾਬੀ: ਲੋਕ-ਸਾਹਿਤ","summary":"ਸਿੱਠਣੀਆਂ ਕੁੜੀ ਦੇ ਵਿਆਹ ਵੇਲੇ ਮੇਲਣਾਂ ਵੱਲੋਂ ਲਾੜੇ ਅਤੇ ਜਾਂਜੀਆਂ ਨੂੰ ਸੰਬੋਧਨ ਕਰ ਕੇ ਗਾਈਆਂ ਜਾਂਦੀਆਂ ਹਾਸ-ਰਸ ਭਰੀਆਂ ਮਿੱਠੀਆਂ ਗਾਲ੍ਹਾਂ ਹਨ, ਜੋ ਵਿਆਹ ਦੇ ਮਾਹੌਲ ਨੂੰ ਖੁਸ਼ਗਵਾਰ ਬਣਾਉਂਦੀਆਂ ਹਨ।","nTerms":5},{"id":"lp11-tappe","title":"ਟੱਪੇ","section":"ਲਾਜ਼ਮੀ ਪੰਜਾਬੀ: ਲੋਕ-ਸਾਹਿਤ","summary":"ਟੱਪਾ ਇਕਹਿਰੀ ਤੁਕ ਵਾਲਾ ਲੋਕ-ਗੀਤ ਹੈ ਜੋ ਢੋਲਕੀ ਨਾਲ ਗਿੱਧੇ ਜਾਂ ਭੰਗੜੇ ਵਿੱਚ ਗਾਇਆ ਜਾਂਦਾ ਹੈ। ਇਸ ਵਿੱਚ ਸੰਜਮ, ਸਰਲਤਾ ਅਤੇ ਤਿੱਖੇ ਇੱਕ-ਭਾਵੀ ਚਿੱਤਰ ਮਿਲਦੇ ਹਨ।","nTerms":5},{"id":"lp11-boliyan","title":"ਲੰਮੀਆਂ ਬੋਲੀਆਂ","section":"ਲਾਜ਼ਮੀ ਪੰਜਾਬੀ: ਲੋਕ-ਸਾਹਿਤ","summary":"ਲੰਮੀਆਂ ਬੋਲੀਆਂ ਭੰਗੜੇ ਅਤੇ ਗਿੱਧੇ ਵਿੱਚ ਸਮੂਹਿਕ ਰੂਪ ਵਿੱਚ ਗਾਇਆ ਜਾਣ ਵਾਲਾ ਲੋਕ-ਕਾਵਿ ਹੈ, ਜਿਸ ਦੀ ਆਖ਼ਰੀ ਛੋਟੀ ਤੁਕ ‘ਤੋੜਾ’ ਸਾਰੇ ਰਲ ਕੇ ਗਾਉਂਦੇ ਹਨ।","nTerms":5},{"id":"lp11-dhole","title":"ਢੋਲੇ","section":"ਲਾਜ਼ਮੀ ਪੰਜਾਬੀ: ਲੋਕ-ਸਾਹਿਤ","summary":"ਢੋਲਾ ਪੱਛਮੀ ਪੰਜਾਬ ਦੀਆਂ ਬਾਰਾਂ ਦਾ ਹਰਮਨ-ਪਿਆਰਾ ਲੋਕ-ਗੀਤ ਹੈ ਜੋ ਬਿਨਾਂ ਸਾਜ਼ ਦੇ ਗਾਇਆ ਜਾਂਦਾ ਹੈ ਅਤੇ ਪਿਆਰ, ਗਿਲੇ-ਸ਼ਿਕਵੇ, ਇਤਿਹਾਸ ਤੇ ਬਾਰ ਦੇ ਜੀਵਨ ਦੀ ਝਲਕ ਦਿੰਦਾ ਹੈ।","nTerms":5},{"id":"lp11-mahiye","title":"ਮਾਹੀਏ","section":"ਲਾਜ਼ਮੀ ਪੰਜਾਬੀ: ਲੋਕ-ਸਾਹਿਤ","summary":"ਮਾਹੀਆ ਤਿੰਨ ਸਤਰਾਂ ਵਾਲਾ ਪ੍ਰੇਮ-ਭਾਵਾਂ ਦਾ ਲੋਕ-ਗੀਤ ਹੈ, ਜਿਸ ਵਿੱਚ ਪਹਿਲੀ ਛੋਟੀ ਸਤਰ ਅਤੇ ਦੂਜੀ ਲੰਮੀ ਤੁਕ ਹੁੰਦੀ ਹੈ। ਇਹ ਪੱਛਮੀ ਪੰਜਾਬ ਵਿੱਚ ਵਧੇਰੇ ਪ੍ਰਚਲਿਤ ਰਿਹਾ ਹੈ।","nTerms":5},{"id":"lp11-bujharatan","title":"ਬੁਝਾਰਤਾਂ","section":"ਲਾਜ਼ਮੀ ਪੰਜਾਬੀ: ਲੋਕ-ਸਾਹਿਤ","summary":"ਬੁਝਾਰਤ ਲੋਕ-ਸਾਹਿਤ ਦਾ ਉਹ ਰੂਪ ਹੈ ਜਿਸ ਵਿੱਚ ਜੀਵਨ ਦੇ ਕਿਸੇ ਪੱਖ ਨੂੰ ਅੜਾਉਣੀ ਦੇ ਰੂਪ ਵਿੱਚ ਪੇਸ਼ ਕਰ ਕੇ ਸੁਣਨ ਵਾਲੇ ਦੀ ਸੂਝ-ਬੂਝ ਅਤੇ ਦਿਮਾਗ਼ੀ ਚੁਸਤੀ ਪਰਖੀ ਜਾਂਦੀ ਹੈ।","nTerms":5},{"id":"lp11-mith-kathavan","title":"ਮਿਥ-ਕਥਾਵਾਂ: ਪ੍ਰਹਿਲਾਦ ਭਗਤ ਅਤੇ ਨਲ-ਦਮਯੰਤੀ","section":"ਲਾਜ਼ਮੀ ਪੰਜਾਬੀ: ਲੋਕ-ਸਾਹਿਤ","summary":"ਮਿਥ-ਕਥਾਵਾਂ ਕਥਾ-ਸਾਹਿਤ ਦਾ ਮੁੱਢਲਾ ਰੂਪ ਹਨ। ਇਸ ਭਾਗ ਵਿੱਚ ਪ੍ਰਹਿਲਾਦ ਭਗਤ ਦੀ ਨੇਕੀ ਦੀ ਜਿੱਤ ਅਤੇ ਨਲ-ਦਮਯੰਤੀ ਦੇ ਵਿਛੋੜੇ ਤੇ ਮੁੜ ਮਿਲਾਪ ਦੀਆਂ ਕਥਾਵਾਂ ਹਨ।","nTerms":5},{"id":"lp11-pari-kathavan","title":"ਪਰੀ-ਕਥਾਵਾਂ: ਨੀਲ ਕਮਲ ਅਤੇ ਸਬਜ਼-ਪਰੀ","section":"ਲਾਜ਼ਮੀ ਪੰਜਾਬੀ: ਲੋਕ-ਸਾਹਿਤ","summary":"ਪਰੀ-ਕਥਾਵਾਂ ਕਲਪਨਾ ਦਾ ਅਨੋਖਾ ਸੰਸਾਰ ਰਚਦੀਆਂ ਹਨ, ਜਿੱਥੇ ਪਰੀਆਂ, ਸ਼ਹਿਜ਼ਾਦੇ, ਬੋਲਦੇ ਪੰਛੀ ਅਤੇ ਰੂਪ ਬਦਲਣ ਵਾਲੇ ਪਾਤਰ ਮਿਲਦੇ ਹਨ। ਇਨ੍ਹਾਂ ਦਾ ਅੰਤ ਸੁਖਾਵਾਂ ਹੁੰਦਾ ਹੈ। ਇਸ ਭਾਗ ਵਿੱਚ ‘ਨੀਲ ਕਮਲ’ ਅਤੇ ‘ਸਬਜ਼-ਪਰੀ’ ਦਿੱਤੀਆਂ ਗਈਆਂ ਹਨ।","nTerms":5},{"id":"lp11-niti-katha","title":"ਨੀਤੀ-ਕਥਾ: ਲਾਲਸਾ ਦੀ ਚੌਕੀ","section":"ਲਾਜ਼ਮੀ ਪੰਜਾਬੀ: ਲੋਕ-ਸਾਹਿਤ","summary":"ਨੀਤੀ-ਕਥਾਵਾਂ ਸਿੱਖਿਆ ਨੂੰ ਸਿੱਧੇ ਉਪਦੇਸ਼ ਦੀ ਥਾਂ ਕਹਾਣੀ ਵਿੱਚ ਪਰੋ ਕੇ ਦਿੰਦੀਆਂ ਹਨ। ‘ਲਾਲਸਾ ਦੀ ਚੌਕੀ’ ਲਾਲਚ ਦੇ ਬੁਰੇ ਅੰਜਾਮ ਦੀ ਨੀਤੀ-ਕਥਾ ਹੈ।","nTerms":5},{"id":"lp11-dant-kathavan","title":"ਦੰਤ-ਕਥਾਵਾਂ: ਪੂਰਨ ਭਗਤ, ਰਾਜਾ ਰਸਾਲੂ, ਦੁੱਲਾ ਭੱਟੀ","section":"ਲਾਜ਼ਮੀ ਪੰਜਾਬੀ: ਲੋਕ-ਸਾਹਿਤ","summary":"ਦੰਤ-ਕਥਾਵਾਂ ਇਤਿਹਾਸ ਦੇ ਕਿਸੇ ਤੱਥ ਉੱਤੇ ਲੋਕ-ਕਲਪਨਾ ਦੀ ਪਰਤ ਚੜ੍ਹਨ ਨਾਲ ਬਣੀਆਂ ਕਥਾਵਾਂ ਹਨ। ਇਸ ਭਾਗ ਵਿੱਚ ਤਿੰਨ ਲੋਕ-ਨਾਇਕਾਂ ਦੀਆਂ ਕਥਾਵਾਂ ਹਨ: ਸ਼ੀਲ ਤੇ ਸੱਚ ਦੇ ਪ੍ਰਤੀਕ ਪੂਰਨ ਭਗਤ, ਜ਼ੁਲਮ ਦੇ ਵਿਰੋਧੀ ਰਾਜਾ ਰਸਾਲੂ ਅਤੇ ਬਾਗ਼ੀ ਨਾਇਕ ਦੁੱਲਾ ਭੱਟੀ।","nTerms":6},{"id":"lp11-preet-kathavan","title":"ਪ੍ਰੀਤ-ਕਥਾਵਾਂ: ਹੀਰ-ਰਾਂਝਾ ਅਤੇ ਮਿਰਜ਼ਾ-ਸਾਹਿਬਾਂ","section":"ਲਾਜ਼ਮੀ ਪੰਜਾਬੀ: ਲੋਕ-ਸਾਹਿਤ","summary":"ਪ੍ਰੀਤ-ਕਥਾਵਾਂ ਵਿੱਚ ਪੰਜਾਬੀ ਗੱਭਰੂ ਅਤੇ ਮੁਟਿਆਰ ਦੇ ਪ੍ਰੇਮ ਦੇ ਜਜ਼ਬੇ, ਕੁਰਬਾਨੀ ਅਤੇ ਰੁਮਾਂਚ ਦਾ ਪ੍ਰਗਟਾਵਾ ਹੁੰਦਾ ਹੈ। ਇਸ ਭਾਗ ਵਿੱਚ ਹੀਰ-ਰਾਂਝਾ ਅਤੇ ਮਿਰਜ਼ਾ-ਸਾਹਿਬਾਂ ਦੀਆਂ ਪ੍ਰੀਤ-ਕਥਾਵਾਂ ਹਨ।","nTerms":6}]}});
